/* React Native: plan topic explanations (concept / explanation / real example), keyed w<module>k<topic> */
const EXPL_RN = {
  "w0k0": {c:"Event loop là cơ chế giúp JavaScript, vốn chỉ có một call stack, chạy được code bất đồng bộ: mỗi khi call stack rỗng, nó lấy công việc đang chờ trong các hàng đợi ra để thực thi.", e:"Code đồng bộ chạy trên <b>call stack</b> cho tới khi xong. Timer, network, I/O do runtime (Hermes và phần native) xử lý bên ngoài; khi có kết quả, callback được xếp vào hàng đợi. <b>Microtask</b> gồm callback của <code>Promise.then/catch/finally</code>, phần code sau <code>await</code> và <code>queueMicrotask</code>; <b>macrotask</b> gồm <code>setTimeout</code>, <code>setInterval</code>, sự kiện I/O. Sau mỗi macrotask, engine xả hết microtask (kể cả microtask mới sinh ra trong lúc xả) rồi mới lấy macrotask kế tiếp. Vì vậy <code>Promise.then</code> luôn chạy trước <code>setTimeout(fn, 0)</code>, và một chuỗi microtask không dứt có thể làm timer không bao giờ chạy. Trong React Native, mọi cập nhật UI do React tạo ra đều xuất phát từ JS thread; JS thread bận thì tap, handler và render đều bị trễ theo.", x:"Màn “Thống kê” của Expense Tracker gom 20.000 giao dịch theo tháng bằng một vòng lặp đồng bộ ngay khi mở màn. Animation chuyển màn khựng, nút Back gần 1 giây mới phản hồi. Cách sửa: để server hoặc SQL tổng hợp, chia việc thành từng lô, hoặc chờ transition kết thúc (sự kiện <code>transitionEnd</code> của navigation) rồi mới tính, trong lúc đó hiện skeleton. Câu đố hay gặp, chú ý <code>await</code> cũng tạo microtask:<pre>async function f() {\n  console.log('1');\n  await null;\n  console.log('2');\n}\nsetTimeout(() =&gt; console.log('3'), 0);\nf();\nPromise.resolve().then(() =&gt; console.log('4'));\nconsole.log('5');\n// 1, 5, 2, 4, 3</pre>"},
  "w0k1": {c:"Closure là một hàm cùng với tham chiếu tới các biến trong scope nơi nó được khai báo, nhờ đó hàm vẫn đọc và ghi được các biến này kể cả khi hàm bên ngoài đã chạy xong.", e:"<ul><li><b>Scope</b>: JS dùng lexical scope, tức là biến được tìm từ scope trong ra ngoài theo vị trí viết code. <code>var</code> có function scope; <code>let</code>/<code>const</code> có block scope (<code>{}</code>, thân <code>for</code>, <code>if</code>).</li><li><b>Closure</b>: hàm giữ tham chiếu tới biến chứ không chép giá trị, nên biến đổi thì closure thấy giá trị mới. Trong React, mỗi lần render lại tạo một bộ biến mới, nên closure tạo ở lần render cũ vẫn giữ giá trị cũ (stale closure).</li><li><b>Hoisting</b>: khai báo được xử lý trước khi chạy code của scope. Function declaration được hoist cả thân hàm; <code>var</code> được hoist và khởi tạo bằng <code>undefined</code>; <code>let</code>, <code>const</code>, <code>class</code> cũng được hoist nhưng chưa được khởi tạo.</li><li><b>TDZ</b> (temporal dead zone): khoảng từ đầu block tới dòng khai báo <code>let</code>/<code>const</code>; truy cập biến trong khoảng này ném <code>ReferenceError</code>. Ngoài ra <code>const</code> chỉ cấm gán lại, nội dung object bên trong vẫn sửa được.</li></ul>", x:"Bug kinh điển: vòng <code>for</code> dùng <code>var</code> tạo 3 nút xoá giao dịch, nhưng bấm nút nào cũng xoá item cuối, vì cả ba callback dùng chung một biến <code>i</code>. Đổi sang <code>let</code> thì mỗi vòng lặp có một binding riêng. Bản React Native của lỗi này là stale closure: callback đăng ký một lần trong <code>useEffect(..., [])</code> luôn đọc state của lần render đầu tiên.<pre>var handlers = [];\nfor (var i = 0; i &lt; 3; i++) handlers.push(() =&gt; i);\nhandlers.map(h =&gt; h()); // [3, 3, 3]\n\nconst fns = [];\nfor (let j = 0; j &lt; 3; j++) fns.push(() =&gt; j);\nfns.map(f =&gt; f()); // [0, 1, 2]\n\nconsole.log(a); // undefined: var được hoist và gán undefined\nvar a = 1;\nconsole.log(b); // ReferenceError: b đang ở TDZ\nlet b = 2;</pre>"},
  "w0k2": {c:"<code>this</code> là giá trị ngữ cảnh được xác định tại thời điểm hàm được gọi chứ không phải lúc khai báo; riêng arrow function không có <code>this</code> của riêng nó mà dùng <code>this</code> của scope bao quanh.", e:"Quy tắc theo thứ tự ưu tiên: gọi bằng <code>new</code> thì <code>this</code> là object mới tạo; gọi qua <code>call</code>/<code>apply</code>/<code>bind</code> thì <code>this</code> là đối số được truyền; gọi dạng <code>obj.method()</code> thì <code>this</code> là <code>obj</code>; gọi trơn <code>fn()</code> thì <code>this</code> là <code>undefined</code> trong strict mode (module ES và thân class luôn là strict). <code>call(ctx, a, b)</code> và <code>apply(ctx, [a, b])</code> gọi hàm ngay, chỉ khác cách truyền tham số; <code>bind(ctx)</code> trả về một hàm mới đã cố định <code>this</code> (và có thể cố định trước một số tham số). Arrow function không có <code>this</code> và <code>arguments</code> riêng, không dùng được với <code>new</code>, và <code>call</code>/<code>bind</code> không đổi được <code>this</code> của nó. Lỗi hay gặp: truyền <code>this.handlePress</code> của class component vào <code>onPress</code> làm mất <code>this</code>; dùng arrow function làm method trong object literal rồi mong <code>this</code> trỏ vào chính object đó.", x:"Một màn cũ của Expense Tracker viết bằng class component crash với lỗi “Cannot read property 'setState' of undefined” khi bấm Lưu, vì method được truyền làm callback và bị gọi trơn. Sửa bằng class field dạng arrow hoặc <code>bind</code> trong constructor; chuyển sang function component thì vấn đề này biến mất.<pre>class AddExpense extends React.Component {\n  state = { saving: false };\n  save() { this.setState({ saving: true }); }         // mất this khi truyền đi\n  saveArrow = () =&gt; this.setState({ saving: true });  // this cố định theo instance\n  render() {\n    return &lt;Button title='Lưu' onPress={this.saveArrow} /&gt;;\n  }\n}\n\nfunction total(a, b) { return this.base + a + b; }\ntotal.call({ base: 1 }, 2, 3);    // 6\ntotal.apply({ base: 1 }, [2, 3]); // 6\nconst fromTen = total.bind({ base: 10 }, 5);\nfromTen(1);                       // 16</pre>"},
  "w0k3": {c:"Promise là object đại diện cho kết quả của một tác vụ bất đồng bộ, ở một trong ba trạng thái pending, fulfilled hoặc rejected; <code>async/await</code> là cú pháp giúp viết code dựa trên Promise theo kiểu tuần tự, dễ đọc.", e:"Hàm <code>async</code> luôn trả về Promise; <code>await</code> tạm dừng hàm đó (không chặn thread) cho tới khi Promise settle, nếu Promise reject thì <code>await</code> ném lỗi và bắt được bằng <code>try/catch</code>. Các combinator:<ul><li><code>Promise.all</code>: chạy song song, reject ngay khi có một promise reject (fail-fast); dùng khi cần đủ mọi kết quả.</li><li><code>Promise.allSettled</code>: chờ tất cả, trả về mảng <code>{status, value | reason}</code>; hợp với các request độc lập.</li><li><code>Promise.race</code>: settle theo promise xong đầu tiên, kể cả khi đó là reject; hay dùng để làm timeout. <code>Promise.any</code> lấy promise fulfilled đầu tiên.</li></ul> Lỗi thường gặp: <code>await</code> lần lượt trong vòng <code>for</code> với các request không phụ thuộc nhau (chậm gấp nhiều lần); quên <code>return</code>/<code>await</code> nên lỗi thoát ra ngoài <code>try/catch</code>; <code>forEach(async ...)</code> không chờ được; Promise reject mà không ai bắt. Lưu ý <code>race</code> không huỷ được request bị thua, muốn huỷ thật phải dùng <code>AbortController</code>.", x:"Dashboard của Expense Tracker gọi 3 API: số dư, giao dịch gần đây, ngân sách. Dùng <code>Promise.all</code> thì chỉ cần API ngân sách lỗi là cả màn trắng; <code>allSettled</code> cho phép hiện phần đã có dữ liệu và báo lỗi riêng từng ô. Thêm timeout để request treo trên mạng yếu không giữ spinner mãi:<pre>function withTimeout&lt;T&gt;(p: Promise&lt;T&gt;, ms: number) {\n  let timer: ReturnType&lt;typeof setTimeout&gt;;\n  const timeout = new Promise&lt;never&gt;((_, reject) =&gt; {\n    timer = setTimeout(() =&gt; reject(new Error('timeout')), ms);\n  });\n  return Promise.race([p, timeout]).finally(() =&gt; clearTimeout(timer));\n}\n\nconst [bal, txs, budget] = await Promise.allSettled([\n  withTimeout(api.balance(), 8000),\n  api.recent(),\n  api.budget(),\n]);\nif (budget.status === 'rejected') showBudgetError(budget.reason);</pre>"},
  "w0k4": {c:"Immutability là nguyên tắc không sửa trực tiếp dữ liệu đang có mà tạo ra bản mới mỗi khi thay đổi, nhờ vậy chỉ cần so sánh tham chiếu là biết dữ liệu có đổi hay không.", e:"React, <code>React.memo</code> và selector của Redux/Zustand đều so sánh bằng tham chiếu (<code>Object.is</code>, gần giống <code>===</code>). Nếu mutate object rồi <code>setState</code> chính object đó, React thấy tham chiếu không đổi và bỏ qua render. Spread <code>{...obj}</code> hay <code>[...arr]</code> chỉ là <b>shallow copy</b>: tầng ngoài cùng là object mới, còn các object lồng bên trong vẫn dùng chung tham chiếu. <b>Deep copy</b> có thể dùng <code>structuredClone</code> ở môi trường hỗ trợ hoặc thư viện; <code>JSON.parse(JSON.stringify(x))</code> làm mất <code>Date</code>, <code>undefined</code>, <code>Map</code>, function. Thực tế ít khi cần deep copy: chỉ tạo mới các nhánh bị đổi, hoặc dùng Immer (có sẵn trong Redux Toolkit) để viết kiểu mutate mà vẫn ra kết quả bất biến. Về so sánh: <code>===</code> không ép kiểu, <code>==</code> ép kiểu ngầm (<code>'0' == 0</code> là true); <code>NaN === NaN</code> là false nhưng <code>Object.is(NaN, NaN)</code> là true; hai object có nội dung giống nhau vẫn khác nhau theo <code>===</code>.", x:"Bug thường gặp: sửa số tiền một giao dịch nhưng danh sách không cập nhật, vì code mutate item rồi gọi <code>setTxs(txs)</code> với đúng mảng cũ. Tệ hơn là copy nông rồi sửa object lồng bên trong, làm đổi luôn dữ liệu gốc đang nằm trong cache.<pre>// Sai: mutate, tham chiếu không đổi nên React bỏ qua\ntxs[i].amount = 50000;\nsetTxs(txs);\n\n// Đúng: mảng mới, chỉ item bị đổi là object mới\nsetTxs(prev =&gt; prev.map(t =&gt; (t.id === id ? { ...t, amount: 50000 } : t)));\n\n// Shallow copy: meta vẫn dùng chung với tx gốc\nconst copy = { ...tx };\ncopy.meta.note = 'đã sửa'; // tx.meta.note cũng bị đổi\nconst safe = { ...tx, meta: { ...tx.meta, note: 'đã sửa' } }; // copy cả nhánh lồng</pre>"},
  "w0k5": {c:"Generics là tham số kiểu, cho phép viết một hàm hoặc kiểu dùng được với nhiều kiểu dữ liệu mà vẫn giữ quan hệ giữa input và output. Union <code>A | B</code> mô tả giá trị thuộc một trong nhiều kiểu, còn narrowing là việc TypeScript thu hẹp union dựa trên các phép kiểm tra trong code.", e:"<ul><li><b>Generics</b>: <code>function first&lt;T&gt;(arr: T[]): T | undefined</code>; ràng buộc bằng <code>extends</code> (<code>&lt;T extends { id: string }&gt;</code>), có thể đặt giá trị mặc định <code>&lt;T = unknown&gt;</code>.</li><li><b>Union và narrowing</b>: TS thu hẹp kiểu sau <code>typeof</code>, <code>instanceof</code>, toán tử <code>in</code>, so sánh <code>===</code>, kiểm tra truthy, <code>Array.isArray</code>.</li><li><b>Discriminated union</b>: các nhánh có chung một field kiểu literal (<code>status</code>, <code>type</code>). <code>switch</code> theo field đó cho ra kiểu chính xác của từng nhánh; nhánh <code>default</code> gán vào biến kiểu <code>never</code> để compiler báo lỗi khi thêm trạng thái mới mà quên xử lý.</li><li><b>Type guard</b>: hàm trả về <code>x is T</code> để tự định nghĩa cách narrowing, ví dụ khi kiểm tra dữ liệu từ API. TS tin hoàn toàn vào guard, nên viết guard sai là mất an toàn kiểu. Từ TS 5.5, compiler tự suy ra type predicate cho một số hàm đơn giản như <code>arr.filter(x =&gt; x !== null)</code>.</li></ul>", x:"State màn tải giao dịch viết bằng nhiều biến rời (<code>isLoading</code>, <code>error</code>, <code>data</code>) dễ rơi vào trạng thái vô lý như vừa loading vừa có error. Đổi sang discriminated union để TS chỉ cho truy cập <code>data</code> khi đã thành công:<pre>type Load&lt;T&gt; =\n  | { status: 'loading' }\n  | { status: 'success'; data: T }\n  | { status: 'error'; error: string };\n\nfunction label(s: Load&lt;Tx[]&gt;): string {\n  switch (s.status) {\n    case 'loading': return 'Đang tải';\n    case 'success': return `${s.data.length} giao dịch`;\n    case 'error': return s.error;\n    default: { const unreachable: never = s; return unreachable; }\n  }\n}\nconst isTx = (v: unknown): v is Tx =&gt;\n  typeof v === 'object' &amp;&amp; v !== null &amp;&amp; 'amount' in v &amp;&amp; 'id' in v;</pre>"},
  "w0k6": {c:"Utility types là các kiểu dựng sẵn của TypeScript dùng để biến đổi một kiểu có sẵn thành kiểu mới (chuyển field thành optional, chọn hoặc bỏ field, tạo object theo tập key...); <code>keyof</code> và <code>typeof</code> là toán tử lấy kiểu từ tập key của một kiểu hoặc từ một giá trị.", e:"<ul><li><code>Partial&lt;T&gt;</code>: mọi field thành optional, hợp với payload PATCH hoặc form đang nhập dở; <code>Required&lt;T&gt;</code> làm ngược lại.</li><li><code>Pick&lt;T, K&gt;</code> / <code>Omit&lt;T, K&gt;</code>: chọn hoặc bỏ field. <code>Omit</code> không báo lỗi khi key không tồn tại, nên gõ sai tên field sẽ bị bỏ qua im lặng.</li><li><code>Record&lt;K, V&gt;</code>: object có tập key K và giá trị V, ví dụ <code>Record&lt;Category, number&gt;</code> cho tổng chi theo danh mục.</li><li><code>ReturnType&lt;typeof fn&gt;</code> lấy kiểu trả về của hàm (với hàm async thì kết hợp <code>Awaited</code>); <code>Parameters&lt;T&gt;</code> lấy tuple tham số.</li><li><code>keyof T</code> cho ra union các key; <code>typeof x</code> đặt ở vị trí kiểu sẽ lấy kiểu của một biến. Kết hợp <code>keyof typeof obj</code> với <code>as const</code> để dẫn kiểu từ một object cấu hình, thay vì khai báo cùng một thông tin hai lần.</li></ul>", x:"Expense Tracker có object cấu hình danh mục. Thay vì khai báo thêm một union danh mục (dễ lệch khi thêm danh mục mới), dẫn kiểu từ chính object đó, và tạo kiểu body request từ model:<pre>const CATEGORIES = {\n  food: 'Ăn uống', transport: 'Đi lại', bills: 'Hoá đơn',\n} as const;\ntype Category = keyof typeof CATEGORIES; // 'food' | 'transport' | 'bills'\n\ninterface Tx { id: string; amount: number; category: Category; createdAt: string }\ntype NewTx = Omit&lt;Tx, 'id' | 'createdAt'&gt;; // body POST\ntype TxPatch = Partial&lt;NewTx&gt;;              // body PATCH\ntype Totals = Record&lt;Category, number&gt;;     // thiếu danh mục nào là lỗi compile\n\nasync function fetchTxs(): Promise&lt;Tx[]&gt; { return []; }\ntype FetchResult = Awaited&lt;ReturnType&lt;typeof fetchTxs&gt;&gt;; // Tx[]</pre>"},
  "w0k7": {c:"ES module là hệ thống module chuẩn của JavaScript, dùng <code>import</code>/<code>export</code> tĩnh. Debounce và throttle là hai kỹ thuật giới hạn tần suất gọi hàm: debounce chỉ chạy khi sự kiện đã ngừng được một khoảng thời gian, còn throttle chạy tối đa một lần trong mỗi khoảng thời gian.", e:"ESM có <code>export</code> dạng named và <code>default</code>; import được phân tích tĩnh nên bundler làm được tree shaking. Binding là “live” (luôn đọc giá trị hiện tại chứ không phải bản sao), và mỗi module chỉ được đánh giá một lần rồi cache, nên state ở module scope là singleton dùng chung cho cả app. <code>import()</code> động trả về Promise, dùng để tải lười. Metro hiểu cú pháp ESM nhưng khả năng tree shaking hạn chế hơn bundler web, vì vậy barrel file (<code>index.ts</code> re-export mọi thứ) có thể kéo cả thư viện vào lúc khởi động. <b>Debounce</b> hợp với ô tìm kiếm, autosave; <b>throttle</b> hợp với scroll, kéo thả, gửi vị trí. Khi tự viết cần: closure giữ timer, gọi với tham số mới nhất, có <code>cancel</code> để huỷ khi unmount; dùng trong component thì tạo bằng <code>useMemo</code>/<code>useRef</code>, không tạo debounce mới mỗi lần render.", x:"Ô tìm kiếm giao dịch gọi API mỗi lần gõ phím: 10 ký tự là 10 request, kết quả về lộn xộn. Debounce 300 ms giảm xuống còn 1 request; throttle dùng cho sự kiện scroll để gửi analytics tối đa 1 lần mỗi giây. Bản throttle dưới đây chỉ chạy ở đầu khoảng (leading), lần gọi cuối có thể bị bỏ; cần trailing thì thêm timer.<pre>export function debounce&lt;A extends unknown[]&gt;(fn: (...a: A) =&gt; void, ms: number) {\n  let t: ReturnType&lt;typeof setTimeout&gt; | undefined;\n  const d = (...args: A) =&gt; {\n    clearTimeout(t);\n    t = setTimeout(() =&gt; fn(...args), ms);\n  };\n  d.cancel = () =&gt; clearTimeout(t);\n  return d;\n}\nexport function throttle&lt;A extends unknown[]&gt;(fn: (...a: A) =&gt; void, ms: number) {\n  let last = 0;\n  return (...args: A) =&gt; {\n    if (Date.now() - last &gt;= ms) { last = Date.now(); fn(...args); }\n  };\n}</pre>"},
  "w1k0": {c:"Render là pha React gọi các component để tính ra cây element mới; commit là pha áp những khác biệt đó lên host tree (trong RN là các view native, thông qua Fabric); reconciliation là thuật toán so sánh cây cũ với cây mới để tìm ra tập thay đổi.", e:"Pha render phải thuần (không side effect) vì có thể bị gọi nhiều lần, bị ngắt hoặc bị bỏ dở khi dùng concurrent rendering; Strict Mode cố ý render hai lần ở môi trường dev để làm lộ code không thuần. Pha commit chạy đồng bộ: cập nhật view, gắn ref, chạy <code>useLayoutEffect</code>, sau đó mới tới <code>useEffect</code>. Re-render không có nghĩa là view bị cập nhật: nếu kết quả không đổi thì commit không đụng tới view nào. Reconciliation dựa trên hai giả định: ở cùng một vị trí mà khác <b>type</b> thì React huỷ cả nhánh con (mất state) và tạo mới; cùng type thì giữ instance và chỉ cập nhật props. Với danh sách, <b>key</b> cho React biết phần tử nào là phần tử nào giữa hai lần render; dùng index làm key gây gán nhầm state khi chèn hoặc xoá, còn <code>Math.random()</code> khiến mọi item bị remount. Ngược lại, đổi key có chủ đích là cách gọn nhất để reset state của một component.", x:"Danh sách ngân sách có một <code>TextInput</code> trên mỗi dòng và dùng index làm key. Xoá dòng đầu tiên thì chữ đang gõ ở dòng 2 “nhảy” lên dòng 1, vì React giữ instance theo vị trí. Đổi sang <code>key={b.id}</code> là hết. Còn khi chuyển giữa các ví và muốn form reset sạch, gắn key theo <code>walletId</code>:<pre>{budgets.map((b, i) =&gt; &lt;BudgetRow key={i} budget={b} /&gt;)}     // sai khi xoá/sắp xếp\n{budgets.map(b =&gt; &lt;BudgetRow key={b.id} budget={b} /&gt;)}       // đúng\n\n// Reset toàn bộ state của form khi đổi ví\n&lt;TxForm key={walletId} walletId={walletId} /&gt;\n\n// Bẫy: khai báo component bên trong component khác\nfunction Screen() {\n  const Row = () =&gt; &lt;Text&gt;Row&lt;/Text&gt;; // type mới mỗi lần render nên luôn remount\n  return &lt;Row /&gt;;\n}</pre>"},
  "w1k1": {c:"<code>useState</code> lưu một giá trị state gắn với vị trí của component trong cây và trả về hàm set để lên lịch render lại; <code>useReducer</code> cũng lưu state nhưng gom toàn bộ logic cập nhật vào một hàm reducer <code>(state, action) =&gt; newState</code>.", e:"Gọi <code>setX</code> không làm biến <code>x</code> đổi ngay trong lần render hiện tại, nó chỉ xếp một cập nhật vào hàng đợi; đọc <code>x</code> ngay sau đó vẫn ra giá trị cũ. Từ React 18, <b>automatic batching</b> gom mọi lần set trong cùng một tick (kể cả trong <code>setTimeout</code>, Promise, native event) thành một lần render. Khi giá trị mới phụ thuộc giá trị cũ, dùng <b>updater function</b> <code>setCount(c =&gt; c + 1)</code>: React chạy lần lượt các updater trên giá trị mới nhất, nên không mất cập nhật và tránh được stale closure. Nếu giá trị mới bằng giá trị cũ theo <code>Object.is</code>, React bỏ qua render. Giá trị khởi tạo tốn kém thì truyền hàm <code>useState(() =&gt; parse(raw))</code> để chỉ chạy một lần. <code>useReducer</code> hợp khi nhiều field đổi cùng nhau hoặc việc chuyển trạng thái có quy tắc (form nhiều bước, giỏ hàng); reducer là hàm thuần nên test riêng được, và <code>dispatch</code> luôn giữ nguyên tham chiếu.", x:"Nút thử nghiệm gọi <code>setCount(count + 1)</code> ba lần liền nhưng số chỉ tăng 1, vì cả ba lần đều đọc <code>count</code> của cùng một lần render. Form thêm giao dịch có số tiền, ghi chú, lỗi validate và trạng thái submit thì dùng reducer để mọi chuyển trạng thái nằm ở một chỗ:<pre>setCount(count + 1); setCount(count + 1);   // tăng 1\nsetCount(c =&gt; c + 1); setCount(c =&gt; c + 1); // tăng 2\n\ntype Action =\n  | { type: 'change'; field: 'amount' | 'note'; value: string }\n  | { type: 'submit' }\n  | { type: 'failed'; error: string };\nfunction reducer(s: FormState, a: Action): FormState {\n  switch (a.type) {\n    case 'change': return { ...s, [a.field]: a.value, error: null };\n    case 'submit': return { ...s, submitting: true };\n    case 'failed': return { ...s, submitting: false, error: a.error };\n  }\n}\nconst [form, dispatch] = useReducer(reducer, initialForm);</pre>"},
  "w1k2": {c:"<code>useEffect</code> dùng để đồng bộ component với các hệ thống bên ngoài React (network, subscription, timer, native module). Effect chạy sau khi commit, còn hàm cleanup chạy trước lần chạy kế tiếp và khi component unmount.", e:"<ul><li><b>Dependency</b>: mảng deps phải chứa mọi giá trị reactive (props, state, hàm khai báo trong component) mà effect dùng; React so từng phần tử bằng <code>Object.is</code>. Object hoặc hàm tạo mới mỗi lần render sẽ làm effect chạy lại liên tục. Không truyền mảng thì effect chạy sau mọi lần render; <code>[]</code> thì chỉ chạy sau lần mount.</li><li><b>Cleanup</b>: huỷ subscription, clear timer, abort request. Ở dev, Strict Mode chạy mount, cleanup rồi mount lại để kiểm tra cleanup có đúng không.</li><li><b>Stale closure</b>: bỏ bớt deps để effect “chỉ chạy một lần” khiến nó đọc mãi giá trị cũ. Sửa bằng updater function, thêm deps, dùng ref, hoặc <code>useEffectEvent</code> (ổn định từ React 19.2).</li><li><b>Race condition khi fetch</b>: hai request chồng nhau, response cũ về sau và ghi đè kết quả mới. Xử lý bằng cờ <code>ignore</code> hoặc <code>AbortController</code> trong cleanup.</li></ul> Không nên dùng effect để tính dữ liệu dẫn xuất từ props/state (tính thẳng trong lúc render) hoặc để xử lý sự kiện người dùng (đặt trong handler).", x:"Màn chi tiết ví: người dùng lướt nhanh từ ví A sang ví B, response của A về muộn và ghi đè, nên màn B hiển thị giao dịch của A. Cleanup huỷ request cũ mỗi khi <code>walletId</code> đổi:<pre>useEffect(() =&gt; {\n  const ctrl = new AbortController();\n  setStatus('loading');\n  fetch(`${API}/wallets/${walletId}/txs`, { signal: ctrl.signal })\n    .then(r =&gt; r.json())\n    .then(data =&gt; { setTxs(data); setStatus('ok'); })\n    .catch(e =&gt; { if (e.name !== 'AbortError') setStatus('error'); });\n  return () =&gt; ctrl.abort(); // chạy khi walletId đổi hoặc khi unmount\n}, [walletId]);</pre> Trong production nên để TanStack Query hoặc RTK Query lo phần này; đoạn trên là cách trình bày bản chất khi bị hỏi."},
  "w1k3": {c:"<code>useRef</code> giữ một giá trị mutable tồn tại suốt vòng đời component, thay đổi nó không gây render. <code>useMemo</code> cache kết quả tính toán, <code>useCallback</code> cache tham chiếu của hàm, còn <code>React.memo</code> bỏ qua việc render lại component khi props mới shallow-equal với props cũ.", e:"<ul><li><code>useRef</code>: giữ tham chiếu tới view (<code>inputRef.current?.focus()</code>), id của timer, hoặc giá trị mới nhất cho callback. Không đọc hay ghi <code>ref.current</code> trong lúc render để quyết định UI.</li><li><code>useMemo</code>: chỉ đáng dùng khi phép tính thật sự nặng (lọc, gom nhóm hàng nghìn item) hoặc khi cần tham chiếu ổn định để làm deps hay props.</li><li><code>useCallback</code>: chỉ có ích khi hàm được truyền vào component đã <code>memo</code>, vào deps của hook khác, hoặc làm <code>renderItem</code> của list.</li><li><code>React.memo</code>: vô tác dụng nếu component cha vẫn truyền object hoặc hàm inline mới mỗi lần, hoặc truyền <code>children</code> là JSX (luôn là object mới).</li></ul> Không nên bọc mọi thứ: mỗi hook đều tốn chi phí so sánh deps và bộ nhớ, và làm code khó đọc hơn. Đo bằng Profiler trước. Khi bật React Compiler (mặc định trong template Expo mới), phần lớn memo viết tay không còn cần thiết, nhưng vẫn phải hiểu để đọc code cũ và debug.", x:"Danh sách 2.000 giao dịch: mỗi phím gõ vào ô tìm kiếm làm mọi dòng render lại; Profiler cho thấy <code>TxRow</code> render hàng nghìn lần mỗi phím. Sửa bằng <code>memo</code> cho row, <code>useCallback</code> cho handler và <code>renderItem</code>, <code>useMemo</code> cho kết quả lọc:<pre>const TxRow = memo(function TxRow({ tx, onPress }: RowProps) {\n  return &lt;Pressable onPress={() =&gt; onPress(tx.id)}&gt;&lt;Text&gt;{tx.note}&lt;/Text&gt;&lt;/Pressable&gt;;\n});\n\nfunction TxList({ txs, query }: { txs: Tx[]; query: string }) {\n  const filtered = useMemo(() =&gt; txs.filter(t =&gt; t.note.includes(query)), [txs, query]);\n  const onPress = useCallback((id: string) =&gt; router.push(`/tx/${id}`), []);\n  const renderItem = useCallback(\n    ({ item }: { item: Tx }) =&gt; &lt;TxRow tx={item} onPress={onPress} /&gt;, [onPress]);\n  return &lt;FlatList data={filtered} keyExtractor={t =&gt; t.id} renderItem={renderItem} /&gt;;\n}</pre>"},
  "w1k4": {c:"Context là cơ chế truyền một giá trị xuống cả cây component mà không phải truyền props qua từng tầng. Component đọc context bằng <code>useContext</code> (hoặc <code>use</code>) sẽ render lại mỗi khi <code>value</code> của Provider gần nhất thay đổi.", e:"React so sánh <code>value</code> của Provider bằng <code>Object.is</code>; nếu khác, <b>mọi</b> consumer đều render lại, và <code>React.memo</code> ở các tầng giữa không chặn được vì context đi thẳng tới consumer. Context cũng không có selector: component chỉ dùng <code>user.name</code> vẫn render khi <code>cart</code> nằm chung trong value thay đổi. Lỗi hay gặp nhất là truyền object literal <code>value={{ user, setUser }}</code>, khiến value là object mới mỗi khi Provider render. Cách xử lý:<ul><li>Memo value bằng <code>useMemo</code>.</li><li>Tách context theo tần suất thay đổi: auth và theme ít đổi, bộ lọc đổi liên tục.</li><li>Tách state và dispatch thành hai context, để component chỉ dispatch không bị render theo state.</li><li>Đặt Provider càng sâu càng tốt, chỉ bọc vùng cần dùng.</li></ul> Dữ liệu đổi thường xuyên mà nhiều nơi chỉ đọc một phần thì nên dùng store có selector (Zustand, Redux). Từ React 19 có thể viết <code>&lt;ThemeContext value={...}&gt;</code> thay cho <code>&lt;ThemeContext.Provider&gt;</code>.", x:"App gói <code>auth</code>, <code>theme</code> và <code>filters</code> chung trong một <code>AppContext</code>. Mỗi lần đổi bộ lọc ngày, cả tab bar, header và màn Settings đều render lại; Profiler cho thấy hơn 300 component bị ảnh hưởng. Tách context:<pre>const FiltersState = createContext&lt;Filters&gt;(defaultFilters);\nconst FiltersDispatch = createContext&lt;Dispatch&lt;FilterAction&gt;&gt;(() =&gt; {});\n\nfunction FiltersProvider({ children }: { children: ReactNode }) {\n  const [filters, dispatch] = useReducer(filtersReducer, defaultFilters);\n  return (\n    &lt;FiltersDispatch value={dispatch}&gt;\n      &lt;FiltersState value={filters}&gt;{children}&lt;/FiltersState&gt;\n    &lt;/FiltersDispatch&gt;\n  );\n}\n// Nút “Xoá lọc” chỉ cần dispatch nên không render lại khi filters đổi\nconst dispatch = useContext(FiltersDispatch);</pre> <code>children</code> được tạo ở component cha nên giữ nguyên tham chiếu, khi <code>FiltersProvider</code> render lại thì chỉ consumer của <code>FiltersState</code> bị ảnh hưởng."},
  "w1k5": {c:"Custom hook là hàm có tên bắt đầu bằng <code>use</code>, đóng gói logic có state và effect để tái sử dụng giữa các component. Composition, render props và compound component là các pattern ghép component với nhau thay vì kế thừa hoặc truyền hàng chục props cấu hình.", e:"<ul><li><b>Custom hook</b> chia sẻ logic chứ không chia sẻ state: mỗi component gọi hook có state riêng. Phải tuân thủ Rules of Hooks (chỉ gọi ở top level, không gọi trong điều kiện hay vòng lặp).</li><li><b>Composition</b>: truyền <code>children</code> hoặc component qua props (slot) để tránh prop drilling và tránh “component vạn năng” có 20 boolean props.</li><li><b>Render props</b>: truyền vào một hàm trả về JSX để nơi dùng tự quyết định cách hiển thị dữ liệu mà component cung cấp; <code>renderItem</code> của FlatList chính là render prop. Phần lớn các trường hợp khác nay đã được custom hook thay thế.</li><li><b>Compound component</b>: một nhóm component dùng chung state ngầm qua context (<code>&lt;Tabs&gt;</code>, <code>&lt;Tabs.List&gt;</code>, <code>&lt;Tabs.Panel&gt;</code>), cho API linh hoạt mà nơi dùng không cần biết state bên trong.</li></ul> Chọn custom hook khi chỉ cần chia sẻ logic; chọn compound component khi cần chia sẻ cả cấu trúc UI.", x:"Nhiều màn của Expense Tracker cần giá trị debounce, nên gói thành hook. Bottom sheet chọn danh mục làm theo kiểu compound component để từng màn tự bố trí các phần bên trong:<pre>function useDebouncedValue&lt;T&gt;(value: T, ms = 300) {\n  const [v, setV] = useState(value);\n  useEffect(() =&gt; {\n    const t = setTimeout(() =&gt; setV(value), ms);\n    return () =&gt; clearTimeout(t);\n  }, [value, ms]);\n  return v;\n}\n\n&lt;CategoryPicker value={cat} onChange={setCat}&gt;\n  &lt;CategoryPicker.Search placeholder='Tìm danh mục' /&gt;\n  &lt;CategoryPicker.List /&gt;\n  &lt;CategoryPicker.Footer&gt;Thêm danh mục mới&lt;/CategoryPicker.Footer&gt;\n&lt;/CategoryPicker&gt;</pre> Bên trong, <code>CategoryPicker</code> tạo một context chứa <code>value</code>, <code>onChange</code> và từ khoá tìm kiếm; <code>List</code> và <code>Search</code> đọc context đó."},
  "w1k6": {c:"Concurrent rendering là khả năng của React (từ bản 18) chuẩn bị UI mới ở nền, có thể tạm dừng hoặc bỏ dở một lần render ít quan trọng để ưu tiên cập nhật khẩn cấp như gõ phím. <code>useTransition</code>, <code>useDeferredValue</code> và Suspense được xây trên khả năng này; React Compiler là công cụ lúc build tự động memo hoá component.", e:"<ul><li><code>useTransition</code>: đánh dấu một cập nhật là không khẩn cấp (<code>startTransition(() =&gt; setTab(t))</code>), kèm <code>isPending</code> để hiện trạng thái; từ React 19, hàm truyền vào có thể là async (Actions).</li><li><code>useDeferredValue</code>: trả về phiên bản “trễ” của một giá trị; input cập nhật ngay, phần render nặng dùng giá trị deferred và có thể bị ngắt giữa chừng.</li><li><b>Suspense</b>: hiện fallback khi cây con đang chờ (code tải bằng <code>lazy</code>, dữ liệu từ thư viện hỗ trợ Suspense hoặc <code>use(promise)</code>); nếu cập nhật nằm trong transition, React giữ UI cũ thay vì hiện lại fallback.</li><li><b>React 19</b>: Actions, <code>useActionState</code>, <code>useOptimistic</code>, <code>use</code>, <code>ref</code> là prop bình thường, <code>&lt;Context&gt;</code> dùng làm Provider.</li><li><b>React Compiler</b> (bản 1.0 ổn định từ 10/2025): phân tích code lúc build và tự chèn memo, với điều kiện code tuân thủ Rules of React; component vi phạm sẽ bị bỏ qua.</li></ul> Concurrent không làm code chạy nhanh hơn hay đa luồng, nó chỉ chia nhỏ việc render và sắp xếp ưu tiên. Trên RN, các tính năng này cần New Architecture (Fabric).", x:"Ô tìm kiếm trên danh sách 5.000 giao dịch bị lag mỗi phím, vì lọc và render lại danh sách chạy đồng bộ. Giữ input cập nhật ngay, còn danh sách dùng giá trị deferred:<pre>function SearchScreen({ txs }: { txs: Tx[] }) {\n  const [query, setQuery] = useState('');\n  const deferred = useDeferredValue(query);\n  const stale = query !== deferred;\n  return (\n    &lt;&gt;\n      &lt;TextInput value={query} onChangeText={setQuery} /&gt;\n      &lt;View style={{ opacity: stale ? 0.6 : 1 }}&gt;\n        &lt;TxResults txs={txs} query={deferred} /&gt;\n      &lt;/View&gt;\n    &lt;/&gt;\n  );\n}</pre> <code>TxResults</code> cần được memo (hoặc do React Compiler memo) thì React mới bỏ qua được lần render với giá trị cũ. Câu hỏi hay gặp: so với debounce, <code>useDeferredValue</code> không có độ trễ cố định mà tự thích ứng theo tốc độ thiết bị."},
  "w1k7": {c:"Error Boundary là component bắt lỗi JavaScript được ném ra trong lúc render, trong lifecycle hoặc constructor của cây con, rồi hiển thị UI dự phòng thay vì để cả cây bị unmount.", e:"Hiện vẫn phải viết Error Boundary bằng class với <code>static getDerivedStateFromError</code> (cập nhật state để render fallback) và <code>componentDidCatch</code> (log lỗi, gửi lên Sentry); thực tế thường dùng thư viện <code>react-error-boundary</code> có sẵn <code>resetKeys</code>, <code>onReset</code>. Boundary <b>không</b> bắt được lỗi trong event handler, code bất đồng bộ (<code>setTimeout</code>, Promise), lỗi trong chính nó, và lỗi native; các lỗi này cần <code>try/catch</code> hoặc để global handler và Sentry ghi nhận. Lỗi không có boundary nào bắt sẽ làm React unmount cả cây: ở dev là màn hình đỏ, ở bản release thì app thường crash. Nên đặt boundary nhiều tầng: một cái ở root (màn “Đã có lỗi, thử lại”) và từng vùng độc lập như widget hay màn hình, để lỗi ở một chỗ không kéo sập cả app. React 19 có thêm option <code>onCaughtError</code> và <code>onUncaughtError</code> khi tạo root để log lỗi tập trung.", x:"Một giao dịch cũ có <code>category: null</code> làm biểu đồ danh mục ném lỗi khi render, và với những người dùng có dữ liệu đó thì cả app crash. Bọc riêng biểu đồ để phần còn lại vẫn dùng được, gửi lỗi lên Sentry, và tự reset khi đổi tháng:<pre>import { ErrorBoundary } from 'react-error-boundary';\n\n&lt;ErrorBoundary\n  resetKeys={[month]}\n  onError={(error, info) =&gt;\n    Sentry.captureException(error, { extra: { componentStack: info.componentStack } })}\n  fallbackRender={({ resetErrorBoundary }) =&gt; (\n    &lt;Pressable onPress={resetErrorBoundary}&gt;\n      &lt;Text&gt;Không hiển thị được biểu đồ. Bấm để thử lại&lt;/Text&gt;\n    &lt;/Pressable&gt;\n  )}&gt;\n  &lt;CategoryChart month={month} /&gt;\n&lt;/ErrorBoundary&gt;</pre> Sau đó vẫn phải sửa gốc: validate dữ liệu từ API và xử lý <code>category</code> rỗng."},
  "w2k0": {c:"Core components là các component dựng sẵn của React Native, mỗi cái ánh xạ trực tiếp sang một view native của nền tảng, ví dụ <code>View</code> thành <code>UIView</code> trên iOS và <code>android.view.View</code> (ViewGroup) trên Android.", e:"<ul><li><code>View</code>: khối layout cơ bản, mặc định là flex container theo chiều dọc.</li><li><code>Text</code>: mọi chuỗi bắt buộc nằm trong <code>Text</code>; Text lồng trong Text thì kế thừa style; <code>numberOfLines</code> để cắt dòng.</li><li><code>Image</code>: ảnh từ mạng phải có kích thước (width/height hoặc <code>aspectRatio</code>); <code>resizeMode</code> (<code>cover</code>, <code>contain</code>...); ảnh trong project nạp bằng <code>require</code>.</li><li><code>Pressable</code>: thay thế các Touchable* cũ, có trạng thái <code>pressed</code>, <code>hitSlop</code> để mở rộng vùng chạm, <code>android_ripple</code>, <code>onLongPress</code>.</li><li><code>ScrollView</code>: render toàn bộ con cùng lúc, chỉ hợp với nội dung ngắn; danh sách dài phải dùng FlatList hoặc FlashList.</li><li><code>TextInput</code>: thường dùng dạng controlled (<code>value</code> + <code>onChangeText</code>), có <code>keyboardType</code>, <code>secureTextEntry</code>, <code>returnKeyType</code>, <code>onSubmitEditing</code>.</li></ul> Lỗi hay gặp: đặt chuỗi trực tiếp trong View (lỗi “Text strings must be rendered within a &lt;Text&gt; component”), render danh sách dài bằng <code>map</code> trong ScrollView, quên kích thước cho ảnh remote nên ảnh không hiện.", x:"Form “Thêm giao dịch” của Expense Tracker: ô số tiền dùng bàn phím số, ảnh hoá đơn hiện đúng tỉ lệ, nút Lưu có phản hồi khi bấm và vùng chạm đủ lớn.<pre>&lt;View style={{ padding: 16, gap: 12 }}&gt;\n  &lt;TextInput value={amount} onChangeText={setAmount}\n    keyboardType='decimal-pad' placeholder='Số tiền' /&gt;\n  &lt;Image source={{ uri: receiptUrl }}\n    style={{ width: '100%', aspectRatio: 3 / 4 }} resizeMode='cover' /&gt;\n  &lt;Pressable onPress={save} hitSlop={8}\n    android_ripple={{ color: '#ddd' }}\n    style={({ pressed }) =&gt; [styles.btn, pressed &amp;&amp; { opacity: 0.7 }]}&gt;\n    &lt;Text style={styles.btnText}&gt;Lưu&lt;/Text&gt;\n  &lt;/Pressable&gt;\n&lt;/View&gt;</pre>"},
  "w2k1": {c:"Layout trong React Native dùng Flexbox do engine Yoga tính toán; khác với web, <code>flexDirection</code> mặc định là <code>column</code>, mọi <code>View</code> đều là flex container, và style được khai báo bằng object JavaScript.", e:"<code>flex: 1</code> nghĩa là chiếm phần không gian còn lại theo tỉ lệ (trong RN, <code>flex</code> chỉ nhận một số). <code>justifyContent</code> canh theo trục chính, <code>alignItems</code> canh theo trục phụ (mặc định <code>stretch</code>); <code>gap</code>, <code>rowGap</code>, <code>columnGap</code> đều được hỗ trợ. Đơn vị là dp (density-independent pixel), không có px/em/rem nhưng có phần trăm. Không có cascade: style không kế thừa, trừ Text lồng trong Text. <code>StyleSheet.create</code> gom style tĩnh và giúp kiểm tra kiểu; style dạng mảng <code>[a, cond &amp;&amp; b]</code> để gộp có điều kiện. <b>Dimension</b>: dùng hook <code>useWindowDimensions()</code> (tự cập nhật khi xoay màn, chia đôi màn hình, máy gập) thay vì <code>Dimensions.get</code> đọc một lần ở module scope. <b>Responsive</b>: ưu tiên flex và phần trăm, đặt breakpoint theo chiều rộng cho tablet, tôn trọng font scale; tránh nhân mọi kích thước theo tỉ lệ màn hình vì chữ và nút sẽ to quá mức trên tablet.", x:"Màn tổng quan hiển thị thẻ thống kê 2 cột trên điện thoại và 4 cột trên tablet hoặc khi xoay ngang. Bản cũ tính <code>width</code> từ <code>Dimensions.get('window')</code> lúc import file nên xoay màn không cập nhật.<pre>function StatsGrid({ items }: { items: Stat[] }) {\n  const cols = useWindowDimensions().width &gt;= 768 ? 4 : 2; // cập nhật khi xoay màn\n  return (\n    &lt;View style={styles.grid}&gt;\n      {items.map(s =&gt; (\n        &lt;View key={s.id} style={[styles.card, { width: `${100 / cols - 2}%` }]}&gt;\n          &lt;Text&gt;{s.value}&lt;/Text&gt;\n        &lt;/View&gt;))}\n    &lt;/View&gt;\n  );\n}\nconst styles = StyleSheet.create({\n  grid: { flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'space-between', rowGap: 12 },\n  card: { padding: 12, borderRadius: 8 },\n});</pre>"},
  "w2k2": {c:"React Native cho phép viết code riêng cho từng nền tảng bằng API <code>Platform</code> (kiểm tra lúc chạy) hoặc bằng phần mở rộng file <code>.ios.tsx</code>/<code>.android.tsx</code>, khi đó Metro tự chọn đúng file lúc tạo bundle.", e:"<code>Platform.OS</code> trả về <code>'ios'</code> hoặc <code>'android'</code> (hoặc <code>'web'</code>); <code>Platform.select({ ios, android, default })</code> chọn giá trị theo nền tảng; <code>Platform.Version</code> cho phiên bản hệ điều hành (Android là số API level, iOS là chuỗi). Lệnh <code>import DatePicker from './DatePicker'</code> sẽ lấy <code>DatePicker.ios.tsx</code> hoặc <code>DatePicker.android.tsx</code> tuỳ nền tảng đang build: hợp khi hai bên khác nhau nhiều; nếu chỉ khác vài dòng thì <code>Platform.select</code> đỡ trùng lặp hơn. Hai file phải giữ cùng interface (nên có type props dùng chung). <b>Shadow</b>: iOS dùng <code>shadowColor</code>, <code>shadowOffset</code>, <code>shadowOpacity</code>, <code>shadowRadius</code>; Android truyền thống dùng <code>elevation</code> (bóng theo Material, không chỉnh chi tiết offset). Từ RN 0.76 có thêm <code>boxShadow</code> cú pháp kiểu CSS chạy trên cả hai nền tảng (chỉ với New Architecture). Bóng trên iOS cần view có <code>backgroundColor</code>, và <code>overflow: 'hidden'</code> sẽ cắt mất bóng.", x:"Thẻ ngân sách trông đẹp trên iPhone nhưng phẳng lì trên Android vì chỉ khai báo shadow kiểu iOS. Còn DatePicker cần UI riêng cho mỗi nền tảng:<pre>const card = {\n  backgroundColor: '#fff',\n  borderRadius: 12,\n  ...Platform.select({\n    ios: { shadowColor: '#000', shadowOpacity: 0.12,\n           shadowRadius: 8, shadowOffset: { width: 0, height: 4 } },\n    android: { elevation: 4 },\n  }),\n};\n// Hoặc một dòng cho cả hai nền tảng (New Architecture):\n// boxShadow: '0 4px 8px rgba(0, 0, 0, 0.12)'\n\n// DatePicker.ios.tsx và DatePicker.android.tsx export cùng props\nimport DatePicker from './DatePicker';</pre>"},
  "w2k3": {c:"FlatList và SectionList là danh sách ảo hoá (virtualized) của React Native: chỉ render các item trong và gần vùng nhìn thấy, rồi gỡ những item đã cuộn ra xa. FlashList của Shopify là thư viện thay thế, tái sử dụng (recycle) view của các ô cũ thay vì tạo view mới.", e:"<ul><li><code>keyExtractor</code>: trả về id ổn định cho mỗi item; nếu thiếu, list dùng <code>item.key</code> hoặc index, dễ gây lỗi khi chèn hoặc xoá.</li><li><code>getItemLayout</code>: khi item có chiều cao cố định, khai báo <code>{length, offset, index}</code> để list khỏi phải đo; <code>scrollToIndex</code> chính xác và cuộn nhanh ít bị ô trắng.</li><li><code>windowSize</code> (mặc định 21, tính theo đơn vị “chiều cao màn hình”): lớn thì ít ô trắng khi cuộn nhanh nhưng tốn bộ nhớ, nhỏ thì ngược lại. Đi cùng là <code>initialNumToRender</code>, <code>maxToRenderPerBatch</code>, <code>removeClippedSubviews</code>.</li><li><code>SectionList</code>: dữ liệu theo nhóm có header, hỗ trợ header dính (<code>stickySectionHeadersEnabled</code>).</li><li><b>FlashList</b>: recycle cell nên ít tạo view, mượt hơn trên máy yếu; v2 viết cho New Architecture và không cần <code>estimatedItemSize</code> nữa. Vì cell được tái sử dụng, state cục bộ trong item có thể “dính” sang item khác; có nhiều loại cell thì khai báo <code>getItemType</code>.</li></ul> Dù dùng list nào, item vẫn cần <code>memo</code> và props ổn định.", x:"Lịch sử 5.000 giao dịch nhóm theo ngày. Với SectionList, <code>getItemLayout</code> khó tính vì xen kẽ header; chuyển sang FlashList với mảng phẳng gồm cả header và dòng giao dịch:<pre>type Row = { type: 'header'; date: string } | { type: 'tx'; tx: Tx };\n\n&lt;FlashList\n  data={rows}\n  keyExtractor={r =&gt; (r.type === 'header' ? `h-${r.date}` : r.tx.id)}\n  getItemType={r =&gt; r.type}          // pool tái sử dụng riêng cho header và dòng\n  stickyHeaderIndices={headerIndices}\n  renderItem={({ item }) =&gt;\n    item.type === 'header' ? &lt;DayHeader date={item.date} /&gt; : &lt;TxRow tx={item.tx} /&gt;}\n/&gt;\n\n// Với FlatList và dòng cao cố định 64:\nconst getItemLayout = (_: unknown, index: number) =&gt;\n  ({ length: 64, offset: 64 * index, index });</pre>"},
  "w2k4": {c:"<code>KeyboardAvoidingView</code> tự đẩy hoặc co nội dung khi bàn phím mở; safe area là vùng màn hình không bị tai thỏ, Dynamic Island hay thanh điều hướng hệ thống che; <code>StatusBar</code> điều khiển thanh trạng thái (màu chữ, ẩn hiện).", e:"<ul><li><b>KeyboardAvoidingView</b>: <code>behavior</code> thường là <code>'padding'</code> trên iOS; trên Android, hệ thống đã tự resize theo <code>windowSoftInputMode=adjustResize</code> nên thường để <code>undefined</code> hoặc <code>'height'</code>. Có header thì cần <code>keyboardVerticalOffset</code> bằng chiều cao header. Form dài nên đặt trong ScrollView với <code>keyboardShouldPersistTaps='handled'</code> để lần bấm nút đầu tiên không chỉ đóng bàn phím. Nhiều team dùng <code>react-native-keyboard-controller</code> để hành vi đồng nhất trên hai nền tảng.</li><li><b>Safe area</b>: <code>SafeAreaView</code> của core đã deprecated (vốn chỉ chạy trên iOS); dùng <code>react-native-safe-area-context</code>: bọc <code>SafeAreaProvider</code> ở root, rồi dùng <code>SafeAreaView</code> với <code>edges</code> hoặc hook <code>useSafeAreaInsets()</code> để chỉ thêm padding ở cạnh cần.</li><li><b>StatusBar</b>: <code>barStyle</code> là <code>'dark-content'</code> hoặc <code>'light-content'</code>; với Expo thì dùng <code>expo-status-bar</code> (<code>style='auto'</code> tự đổi theo dark mode).</li></ul> Android 15 bắt buộc edge-to-edge với app target SDK 35, nên xử lý inset trên Android giờ quan trọng không kém iOS.", x:"Màn “Thêm giao dịch”: trên iPhone, bàn phím che nút Lưu; trên Android, nút Lưu bị thanh điều hướng che vì app chạy edge-to-edge. Kết hợp đúng cả ba (<code>headerHeight</code> lấy từ <code>useHeaderHeight()</code> của React Navigation, <code>StatusBar</code> từ <code>expo-status-bar</code>):<pre>import { useSafeAreaInsets } from 'react-native-safe-area-context';\nfunction AddTxScreen() {\n  const insets = useSafeAreaInsets();\n  return (\n    &lt;KeyboardAvoidingView style={{ flex: 1 }}\n      behavior={Platform.OS === 'ios' ? 'padding' : undefined}\n      keyboardVerticalOffset={headerHeight}&gt;\n      &lt;StatusBar style='auto' /&gt;\n      &lt;ScrollView keyboardShouldPersistTaps='handled'\n        contentContainerStyle={{ padding: 16, paddingBottom: insets.bottom + 16 }}&gt;\n        &lt;TxForm onSubmit={save} /&gt;\n      &lt;/ScrollView&gt;\n    &lt;/KeyboardAvoidingView&gt;\n  );\n}</pre>"},
  "w2k5": {c:"React Native Gesture Handler nhận diện cử chỉ (pan, tap, pinch...) ngay ở tầng native, còn Reanimated cho phép viết animation bằng JavaScript nhưng chạy trên UI thread, thông qua worklet và shared value.", e:"<ul><li><b>Worklet</b>: hàm JS nhỏ được tách ra chạy trên một runtime JS riêng ở UI thread; callback của <code>useAnimatedStyle</code>, <code>useDerivedValue</code> và callback của gesture (khi có Reanimated) tự động được biến thành worklet. Từ Reanimated 4, phần worklet tách thành package <code>react-native-worklets</code>, và Reanimated 4 chỉ hỗ trợ New Architecture.</li><li><b>Shared value</b> (<code>useSharedValue</code>): giá trị đọc ghi qua <code>.value</code> được từ cả hai thread; đổi nó không làm React render lại mà cập nhật thẳng style trên UI thread.</li><li><b>UI thread</b>: gesture và animation chạy tại đây nên vẫn mượt khi JS thread bận. Muốn gọi code JS thường (setState, điều hướng, gọi API) từ worklet thì phải chuyển về JS thread bằng <code>scheduleOnRN</code> (tên cũ là <code>runOnJS</code>).</li></ul> Gesture Handler 2 dùng API <code>Gesture.Pan()</code>, <code>Gesture.Tap()</code>, ghép bằng <code>Gesture.Simultaneous/Exclusive/Race</code>, gắn vào view qua <code>&lt;GestureDetector&gt;</code>, và app phải được bọc trong <code>GestureHandlerRootView</code>. Lỗi hay gặp: đọc <code>.value</code> trong lúc render, gọi hàm JS thường trực tiếp trong worklet gây crash, quên root view.", x:"Swipe-to-delete trong danh sách giao dịch: kéo sang trái quá 120 dp thì xoá, chưa đủ thì bật về chỗ cũ. Toàn bộ chuyển động chạy trên UI thread, chỉ lệnh xoá quay về JS thread:<pre>const x = useSharedValue(0);\nconst pan = Gesture.Pan()\n  .activeOffsetX([-10, 10])                 // để list vẫn cuộn dọc được\n  .onUpdate(e =&gt; { x.value = Math.min(0, e.translationX); })\n  .onEnd(() =&gt; {\n    x.value = x.value &lt; -120\n      ? withTiming(-500, {}, () =&gt; scheduleOnRN(onDelete, tx.id))\n      : withSpring(0);\n  });\nconst style = useAnimatedStyle(() =&gt; ({ transform: [{ translateX: x.value }] }));\n\n&lt;GestureDetector gesture={pan}&gt;\n  &lt;Animated.View style={style}&gt;&lt;TxRow tx={tx} /&gt;&lt;/Animated.View&gt;\n&lt;/GestureDetector&gt;</pre>"},
  "w2k6": {c:"Xử lý ảnh trong RN gồm ba việc chính: cache ảnh tải từ mạng để không tải lại, decode ảnh ở kích thước gần với kích thước hiển thị để tiết kiệm bộ nhớ, và hiển thị đồ hoạ vector (SVG) cho icon và biểu đồ.", e:"<ul><li><b>Cache</b>: <code>Image</code> của core có cache cơ bản, hành vi khác nhau giữa iOS và Android. <code>expo-image</code> (dùng SDWebImage trên iOS, Glide trên Android) có cache bộ nhớ và đĩa, <code>placeholder</code> bằng blurhash/thumbhash, <code>transition</code>, <code>recyclingKey</code> cho list, <code>cachePolicy</code>, <code>Image.prefetch</code>. <code>react-native-fast-image</code> từng phổ biến nhưng gần như không còn được bảo trì, dự án mới nên chọn <code>expo-image</code>.</li><li><b>Resize</b>: bitmap tốn bộ nhớ theo số pixel (rộng × cao × 4 byte); ảnh 4000×3000 chiếm khoảng 48 MB khi decode dù chỉ hiện làm thumbnail 64 dp. Nên để server hoặc CDN trả ảnh đúng cỡ, và nén, thu nhỏ ảnh trước khi upload (ví dụ bằng <code>expo-image-manipulator</code>).</li><li><b>SVG</b>: <code>react-native-svg</code> để vẽ; <code>react-native-svg-transformer</code> cho phép import file <code>.svg</code> như một component. SVG phức tạp render hàng trăm lần trong list có thể nặng hơn PNG, khi đó cân nhắc icon font hoặc ảnh raster.</li></ul>", x:"Danh sách hoá đơn hiển thị thumbnail từ ảnh chụp camera 12 MP. Trên máy Android 3 GB RAM, cuộn vài chục dòng là app bị kill vì hết bộ nhớ. Cách sửa: upload ảnh đã thu nhỏ, server trả thumbnail theo kích thước, list dùng <code>expo-image</code> với <code>recyclingKey</code>:<pre>import { Image } from 'expo-image';\n\n&lt;Image\n  source={{ uri: `${CDN}/receipts/${r.id}?w=128` }}  // 2x của 64 dp\n  placeholder={{ blurhash: r.blurhash }}\n  recyclingKey={r.id}       // tránh hiện ảnh cũ khi cell được tái sử dụng\n  cachePolicy='memory-disk'\n  transition={150}\n  contentFit='cover'\n  style={{ width: 64, height: 64, borderRadius: 8 }}\n/&gt;</pre>"},
  "w2k7": {c:"Accessibility trong RN là việc cung cấp thông tin cho trình đọc màn hình (VoiceOver trên iOS, TalkBack trên Android) và tôn trọng thiết lập của người dùng như cỡ chữ lớn, để người khuyết tật cũng dùng được app.", e:"<ul><li><code>accessibilityLabel</code> (hoặc <code>aria-label</code>): tên được đọc lên cho phần tử không có chữ, như nút chỉ có icon; <code>accessibilityHint</code> mô tả kết quả của hành động.</li><li><code>role</code> (được ưu tiên hơn <code>accessibilityRole</code> nếu khai báo cả hai): cho biết phần tử là <code>button</code>, <code>heading</code>, <code>checkbox</code>, <code>switch</code>, <code>link</code>, <code>img</code>...; trạng thái khai báo qua <code>accessibilityState</code> hoặc <code>aria-checked</code>, <code>aria-disabled</code>, <code>aria-selected</code>.</li><li><code>accessible={true}</code> gộp một nhóm view thành một phần tử được đọc liền mạch; <code>importantForAccessibility</code> (Android) để ẩn phần trang trí.</li><li><b>Dynamic font size</b>: <code>Text</code> mặc định phóng to theo cài đặt cỡ chữ hệ thống (<code>allowFontScaling</code> mặc định là true). Không nên tắt; dùng <code>maxFontSizeMultiplier</code> để giới hạn ở chỗ chật, và thiết kế layout co giãn (không cố định chiều cao khung chứa chữ). <code>useWindowDimensions().fontScale</code> cho biết hệ số hiện tại.</li></ul> Thêm: vùng chạm tối thiểu khoảng 44×44 pt (iOS) hoặc 48×48 dp (Android), độ tương phản màu đủ, và kiểm tra thật bằng VoiceOver/TalkBack.", x:"Kiểm tra Expense Tracker bằng TalkBack: nút xoá chỉ có icon thùng rác nên được đọc là “button, unlabeled”; số tiền và danh mục bị đọc thành ba mục rời; bật cỡ chữ lớn nhất thì số tiền bị cắt. Sửa:<pre>&lt;Pressable\n  onPress={() =&gt; remove(tx.id)}\n  role='button'\n  accessibilityLabel={`Xoá giao dịch ${tx.note}`}\n  accessibilityHint='Giao dịch sẽ bị xoá vĩnh viễn'\n  hitSlop={12}&gt;\n  &lt;TrashIcon /&gt;\n&lt;/Pressable&gt;\n\n&lt;View accessible accessibilityLabel={`${tx.category}, ${formatVND(tx.amount)}, ${tx.date}`}&gt;\n  &lt;Text&gt;{tx.category}&lt;/Text&gt;\n  &lt;Text maxFontSizeMultiplier={1.6}&gt;{formatVND(tx.amount)}&lt;/Text&gt;\n&lt;/View&gt;</pre>"},
  "w3k0": {c:"React Navigation là thư viện điều hướng phổ biến nhất cho RN, quản lý lịch sử màn hình bằng các navigator (stack, tab, drawer) có thể lồng nhau, và khớp với hành vi native như nút back, cử chỉ vuốt để quay lại.", e:"<ul><li><b>Stack</b>: <code>createNativeStackNavigator</code> dùng navigation native của từng nền tảng nên được ưu tiên; các thao tác <code>navigate</code>, <code>push</code>, <code>replace</code>, <code>goBack</code>, <code>popToTop</code>.</li><li><b>Tab</b> (bottom tabs): mỗi tab thường chứa một stack riêng. <b>Drawer</b>: menu trượt từ cạnh màn hình (cần Gesture Handler và Reanimated).</li><li><b>Nested</b>: đặt tab navigator bên trong stack gốc để màn chi tiết che được cả tab bar; điều hướng vào màn của navigator con bằng <code>navigate('Main', { screen: 'Reports', params })</code>; mỗi navigator có header và option riêng.</li><li><b>Params có type</b>: khai báo <code>type RootStackParamList = { TxDetail: { txId: string } }</code> (phải là <code>type</code>, không dùng <code>interface</code>), truyền vào <code>createNativeStackNavigator&lt;RootStackParamList&gt;()</code>, rồi dùng <code>NativeStackScreenProps&lt;RootStackParamList, 'TxDetail'&gt;</code> cho props của màn. Bản 7 có thêm static API để suy ra type tự động.</li></ul> Params chỉ nên chứa id và dữ liệu nhỏ, serialize được (phục vụ deep link và lưu state điều hướng); không truyền cả object giao dịch hay callback, màn đích tự lấy dữ liệu từ cache theo id.", x:"Expense Tracker có stack gốc chứa tab navigator (Home, Reports, Settings) và màn <code>TxDetail</code>. Gõ sai tên params là compiler báo ngay:<pre>type RootStackParamList = {\n  Main: NavigatorScreenParams&lt;TabParamList&gt;;\n  TxDetail: { txId: string };\n};\nconst Stack = createNativeStackNavigator&lt;RootStackParamList&gt;();\n\ntype Props = NativeStackScreenProps&lt;RootStackParamList, 'TxDetail'&gt;;\nfunction TxDetailScreen({ route, navigation }: Props) {\n  const { data: tx } = useTx(route.params.txId); // chỉ truyền id qua params\n  return &lt;TxDetailView tx={tx} onClose={navigation.goBack} /&gt;;\n}\n\n// Mở màn Reports nằm trong tab navigator Main, kèm params\nnavigation.navigate('Main', { screen: 'Reports', params: { month: '2026-10' } });</pre>"},
  "w3k1": {c:"Expo Router là thư viện điều hướng dựa trên file, xây trên React Navigation: mỗi file trong thư mục <code>app/</code> là một route, và đường dẫn URL cũng như deep link được sinh tự động từ cấu trúc thư mục.", e:"<code>app/index.tsx</code> ứng với <code>/</code>; <code>app/tx/[id].tsx</code> là route động, đọc tham số bằng <code>useLocalSearchParams()</code>; <code>_layout.tsx</code> khai báo navigator (Stack, Tabs) cho thư mục chứa nó; thư mục đặt trong ngoặc như <code>(auth)</code>, <code>(app)</code> là <b>group</b>, dùng để tổ chức mà không xuất hiện trong URL; <code>+not-found.tsx</code> cho route không tồn tại. Điều hướng bằng <code>&lt;Link href&gt;</code> hoặc <code>router.push/replace</code>; bật typed routes thì TS báo lỗi khi href sai. <b>Auth flow</b>: nguyên tắc giống React Navigation, chọn nhóm màn theo trạng thái đăng nhập thay vì tự <code>navigate</code> sau khi login. Cách hiện tại là <code>Stack.Protected guard={...}</code>: khi guard sai thì route không truy cập được; khi guard đổi từ đúng sang sai (logout), router tự đưa người dùng ra và xoá lịch sử của các màn đó. Giữ splash screen cho tới khi đọc xong token để không nháy màn login. Guard chỉ bảo vệ ở phía client, API vẫn phải tự kiểm tra quyền.", x:"Cấu trúc auth của Expense Tracker gồm <code>app/_layout.tsx</code> (Stack gốc), <code>app/sign-in.tsx</code>, <code>app/(app)/_layout.tsx</code> (Tabs) và <code>app/(app)/tx/[id].tsx</code>. Layout gốc đọc session từ secure store rồi quyết định nhóm màn được phép vào; <code>SplashScreen.preventAutoHideAsync()</code> giữ splash tới khi có kết quả:<pre>// app/_layout.tsx\nexport default function RootLayout() {\n  const { session, isLoading } = useSession();\n  if (isLoading) return null; // splash native vẫn đang hiện\n  return (\n    &lt;Stack screenOptions={{ headerShown: false }}&gt;\n      &lt;Stack.Protected guard={!!session}&gt;\n        &lt;Stack.Screen name='(app)' /&gt;\n      &lt;/Stack.Protected&gt;\n      &lt;Stack.Protected guard={!session}&gt;\n        &lt;Stack.Screen name='sign-in' /&gt;\n      &lt;/Stack.Protected&gt;\n    &lt;/Stack&gt;\n  );\n}</pre> Khi logout, chỉ cần xoá session: guard đổi và router tự chuyển về <code>sign-in</code>."},
  "w3k2": {c:"Deep link là URL mở thẳng vào một màn hình cụ thể trong app. Universal link (iOS) và App Link (Android) là deep link dùng domain https thật đã được xác minh, nên mở app nếu đã cài và mở trang web nếu chưa cài.", e:"<ul><li><b>Custom scheme</b> (<code>expensetracker://tx/42</code>): dễ cấu hình, nhưng app khác có thể đăng ký trùng scheme, và nếu chưa cài app thì link không mở được gì.</li><li><b>Universal link</b>: domain host file <code>apple-app-site-association</code> trong <code>/.well-known/</code>, khai báo app ID và các path; app bật entitlement Associated Domains <code>applinks:example.com</code>.</li><li><b>App Link</b>: domain host <code>/.well-known/assetlinks.json</code> chứa package name và SHA-256 của chứng chỉ ký (dùng fingerprint của app signing key trên Play Console, không phải upload key); intent-filter có <code>android:autoVerify='true'</code>.</li><li><b>Linking config</b>: React Navigation nhận <code>linking={{ prefixes, config: { screens } }}</code> để ánh xạ path sang màn hình và params; Expo Router tự sinh từ cấu trúc file. Khi app đang tắt (cold start), URL lấy qua <code>Linking.getInitialURL()</code>; khi app đang chạy thì qua sự kiện <code>url</code>; thư viện navigation đã xử lý cả hai.</li></ul> Luôn validate params từ link (đây là input không tin cậy) và xử lý trường hợp chưa đăng nhập: lưu link lại, login xong mới điều hướng. Firebase Dynamic Links đã ngừng hoạt động, nên deferred deep link (mở đúng màn sau khi cài app) phải dùng giải pháp khác.", x:"Email nhắc ngân sách chứa link <code>https://app.example.com/tx/42</code>. Người đã cài app thì mở thẳng màn chi tiết giao dịch, chưa cài thì xem trên web. Cấu hình React Navigation và cách thử:<pre>const linking: LinkingOptions&lt;RootStackParamList&gt; = {\n  prefixes: ['https://app.example.com', 'expensetracker://'],\n  config: {\n    screens: {\n      Main: { screens: { Home: '', Reports: 'reports/:month' } },\n      TxDetail: 'tx/:txId',\n    },\n  },\n};\n&lt;NavigationContainer linking={linking} fallback={&lt;Splash /&gt;}&gt;&lt;RootStack /&gt;&lt;/NavigationContainer&gt;\n\n// Android: adb shell am start -a android.intent.action.VIEW -d 'https://app.example.com/tx/42'\n// iOS simulator: xcrun simctl openurl booted 'https://app.example.com/tx/42'</pre>"},
  "w3k3": {c:"Server state là dữ liệu có nguồn chân lý nằm ở backend, app chỉ giữ một bản sao có thể đã cũ; client state là dữ liệu chỉ tồn tại trong app và do app sở hữu hoàn toàn, như theme, bộ lọc đang chọn, form đang nhập.", e:"Server state có những bài toán riêng: cache, trạng thái loading/error, refetch khi quay lại màn hoặc khi có mạng lại, gộp request trùng (dedupe), phân trang, invalidate sau khi ghi, optimistic update, đồng bộ giữa nhiều màn. Các thư viện chuyên dụng như TanStack Query, RTK Query, hay Apollo cho GraphQL đã giải quyết sẵn những việc này. Client state đơn giản hơn: đồng bộ, không bao giờ “cũ”, chỉ cần chỗ lưu và cách chia sẻ (useState, Context, Zustand, Redux slice), có thể persist bằng MMKV. Sai lầm phổ biến là nhét response API vào Redux bằng tay rồi tự viết <code>isLoading</code>, <code>error</code>, <code>lastFetched</code> cho từng màn; hoặc copy server state vào <code>useState</code> khiến hai nguồn dữ liệu lệch nhau. Có một vùng xám: với app offline-first, DB local trở thành nguồn hiển thị, còn lớp sync lo đồng bộ với server.", x:"Khi được hỏi “bạn quản lý state thế nào”, phân loại state của Expense Tracker:<ul><li>Server state (TanStack Query): danh sách giao dịch, số dư, ngân sách, hồ sơ người dùng.</li><li>Client state toàn cục (Zustand, persist bằng MMKV): theme, đơn vị tiền, tháng đang lọc, cờ đã xem onboarding.</li><li>State cục bộ (useState/useReducer): form đang nhập, bottom sheet đóng hay mở.</li><li>Bí mật (secure store): access token, refresh token.</li></ul><pre>// Client state: chỉ app sở hữu\nconst month = useFilterStore(s =&gt; s.month);\n\n// Server state: thư viện lo cache, refetch, dedupe\nconst { data: txs, isPending } = useQuery({\n  queryKey: ['txs', month],\n  queryFn: () =&gt; api.txs(month),\n});</pre>"},
  "w3k4": {c:"Redux Toolkit (RTK) là bộ công cụ chính thức để viết Redux ngắn gọn: <code>createSlice</code> sinh reducer và action, <code>createAsyncThunk</code> xử lý tác vụ bất đồng bộ, RTK Query lo fetch và cache dữ liệu server. Redux-Saga là middleware xử lý side effect bằng generator function.", e:"<ul><li><b>Slice</b>: reducer viết kiểu “mutate” nhưng Immer chuyển thành cập nhật bất biến; action creator và action type được sinh tự động.</li><li><b>createAsyncThunk</b>: tự dispatch <code>pending</code>, <code>fulfilled</code>, <code>rejected</code>, xử lý trong <code>extraReducers</code>; có <code>rejectWithValue</code>, <code>condition</code>, và <code>signal</code> để huỷ.</li><li><b>RTK Query</b>: <code>createApi</code> với các endpoint <code>query</code>/<code>mutation</code>, sinh hook như <code>useGetTxsQuery</code>; cache theo tham số, <code>providesTags</code>/<code>invalidatesTags</code> để tự refetch sau khi ghi, có dedupe và polling. Đã dùng RTK Query thì không cần viết thunk cho việc fetch.</li><li><b>Redux-Saga</b>: <code>takeLatest</code> (huỷ task cũ khi action mới tới, hợp với tìm kiếm), <code>takeEvery</code>, <code>call</code> (gọi hàm trả Promise, dễ mock khi test), <code>put</code> (dispatch action), <code>fork</code> (chạy task con không chặn, lỗi lan lên task cha), <code>spawn</code> (task tách biệt), <code>race</code>, <code>delay</code>, <code>cancel</code>.</li></ul> Saga mạnh với flow dài, cần huỷ, polling, nhưng khó đọc và khó debug; dự án mới thường chọn RTK Query cộng listener middleware, còn Saga hay gặp ở codebase cũ.", x:"Dự án cũ dùng Saga cho tìm kiếm giao dịch, đoạn này hay bị yêu cầu viết tại chỗ; bên dưới là phần CRUD tương đương bằng RTK Query:<pre>function* searchTx(action: PayloadAction&lt;string&gt;) {\n  yield delay(300);                    // cùng takeLatest tạo thành debounce\n  try {\n    const data: Tx[] = yield call(api.search, action.payload);\n    yield put(searchSucceeded(data));\n  } catch (e) { yield put(searchFailed(String(e))); }\n}\nexport function* rootSaga() {\n  yield all([takeLatest(searchRequested.type, searchTx), fork(watchSync)]);\n}\nconst txApi = createApi({ baseQuery: fetchBaseQuery({ baseUrl: API }), tagTypes: ['Tx'],\n  endpoints: b =&gt; ({\n    getTxs: b.query&lt;Tx[], string&gt;({ query: m =&gt; `txs?month=${m}`, providesTags: ['Tx'] }),\n    addTx: b.mutation&lt;Tx, NewTx&gt;({ query: body =&gt; ({ url: 'txs', method: 'POST', body }), invalidatesTags: ['Tx'] }),\n  }) });</pre>"},
  "w3k5": {c:"Zustand là thư viện store nhỏ gọn dựa trên hook, component đọc state qua selector. MobX là thư viện state theo mô hình reactive: nó tự theo dõi component đọc những observable nào để chỉ render lại đúng các component đó.", e:"<ul><li><b>Zustand</b>: <code>create</code> trả về một hook; component chỉ render lại khi phần state mà selector chọn thay đổi. Không cần Provider, ít boilerplate, có middleware <code>persist</code> (kết hợp được với MMKV), <code>devtools</code>, <code>immer</code>; đọc ghi được cả ngoài React qua <code>getState</code>/<code>setState</code>. Nhược điểm: ít quy ước nên team lớn dễ mỗi người viết một kiểu; selector trả về object hoặc mảng mới phải bọc <code>useShallow</code>, nếu không component sẽ render lại liên tục, thậm chí lặp vô hạn.</li><li><b>MobX</b>: <code>makeAutoObservable</code> cho class store, bọc component bằng <code>observer</code>; cập nhật bằng cách mutate trực tiếp nên viết nhanh, hiệu năng tốt vì theo dõi tới từng field. Nhược điểm: cơ chế ngầm khó lần theo, quên <code>observer</code> là UI không cập nhật, phong cách khác hẳn hướng bất biến của React.</li><li><b>So với Redux</b>: Redux có luồng dữ liệu rõ ràng, devtools time-travel, middleware và quy ước chặt, hợp team lớn và logic phức tạp, đổi lại nhiều boilerplate hơn (RTK đã giảm đáng kể).</li></ul> Nên chọn theo quy mô team, nhu cầu devtools, và việc server state đã có TanStack Query lo hay chưa: khi đã có, phần client state còn lại thường nhỏ và Zustand là đủ.", x:"Store cài đặt và bộ lọc của Expense Tracker bằng Zustand, persist bằng MMKV, kèm cách viết selector đúng:<pre>const storage = createMMKV();\nexport const useSettings = create&lt;Settings&gt;()(persist(\n  set =&gt; ({\n    currency: 'VND', month: thisMonth(),\n    setMonth: month =&gt; set({ month }),\n  }),\n  { name: 'settings', storage: createJSONStorage(() =&gt; ({\n      getItem: k =&gt; storage.getString(k) ?? null,\n      setItem: (k, v) =&gt; storage.set(k, v),\n      removeItem: k =&gt; { storage.remove(k); } })) }));\n\nconst month = useSettings(s =&gt; s.month);            // chỉ render khi month đổi\nconst { currency, setMonth } = useSettings(\n  useShallow(s =&gt; ({ currency: s.currency, setMonth: s.setMonth })));</pre>"},
  "w3k6": {c:"TanStack Query là thư viện quản lý server state: nó gọi API, cache kết quả theo <code>queryKey</code>, tự refetch theo quy tắc dữ liệu cũ (stale), và cung cấp mutation để ghi dữ liệu kèm invalidate hoặc optimistic update.", e:"<ul><li><b>Cache</b>: mỗi query xác định bởi <code>queryKey</code> (một mảng, nên chứa mọi tham số như <code>['txs', month]</code>); các component dùng cùng key chia sẻ một request và một bản cache.</li><li><b>staleTime</b> (mặc định 0): trong khoảng này dữ liệu được coi là mới và không bị refetch. <b>gcTime</b> (v5 đổi tên từ <code>cacheTime</code>, mặc định 5 phút): thời gian giữ cache sau khi không còn component nào dùng query. Nhầm hai khái niệm này là câu hỏi bẫy hay gặp.</li><li><b>Invalidate</b>: sau mutation gọi <code>queryClient.invalidateQueries({ queryKey: ['txs'] })</code> để đánh dấu cũ và refetch những query đang hiển thị (khớp theo tiền tố key).</li><li><b>Optimistic update</b>: trong <code>onMutate</code>, huỷ query đang chạy (<code>cancelQueries</code>), lưu snapshot, rồi <code>setQueryData</code> bằng dữ liệu dự kiến; <code>onError</code> khôi phục từ snapshot; <code>onSettled</code> invalidate để đồng bộ lại với server.</li></ul> Trên RN phải nối <code>focusManager</code> với <code>AppState</code> và <code>onlineManager</code> với NetInfo, vì mặc định các sự kiện focus và online là của trình duyệt.", x:"Thêm giao dịch khi mạng chậm: bấm Lưu là item hiện ngay trong danh sách; nếu server báo lỗi thì item biến mất và hiện thông báo:<pre>const qc = useQueryClient();\nconst addTx = useMutation({\n  mutationFn: api.addTx,\n  onMutate: async (newTx: NewTx) =&gt; {\n    await qc.cancelQueries({ queryKey: ['txs'] });\n    const prev = qc.getQueryData&lt;Tx[]&gt;(['txs', month]);\n    qc.setQueryData&lt;Tx[]&gt;(['txs', month], old =&gt;\n      [{ ...newTx, id: `tmp-${Date.now()}` } as Tx, ...(old ?? [])]);\n    return { prev };\n  },\n  onError: (_e, _v, ctx) =&gt; qc.setQueryData(['txs', month], ctx?.prev),\n  onSettled: () =&gt; qc.invalidateQueries({ queryKey: ['txs'] }),\n});</pre>"},
  "w3k7": {c:"Đây là các lựa chọn lưu dữ liệu cục bộ trên thiết bị: AsyncStorage và MMKV là kho key-value, còn SQLite, WatermelonDB, Realm là cơ sở dữ liệu có truy vấn. Offline-first là kiến trúc coi dữ liệu local là nguồn hiển thị chính và đồng bộ với server khi có mạng.", e:"<ul><li><b>AsyncStorage</b>: key-value, API bất đồng bộ, chỉ lưu string, không mã hoá; đủ cho vài cờ cấu hình nhỏ.</li><li><b>MMKV</b>: key-value viết bằng C++ dựa trên mmap, truy cập đồng bộ qua JSI nên rất nhanh, hỗ trợ <code>encryptionKey</code>; hợp để persist store và cache nhỏ. Nó không phải DB: không có truy vấn, không hợp với hàng chục nghìn bản ghi.</li><li><b>SQLite</b> (<code>expo-sqlite</code>, <code>op-sqlite</code>): dữ liệu quan hệ, index, transaction, migration; thường kết hợp ORM như Drizzle.</li><li><b>WatermelonDB</b>: xây trên SQLite, lazy load, query dạng observable, có sẵn giao thức sync pull/push để tự viết backend đồng bộ.</li><li><b>Realm</b>: object DB nhanh, nhưng MongoDB đã deprecate Atlas Device Sync cùng các Realm SDK (end-of-life 09/2025), nên cần cân nhắc kỹ cho dự án mới.</li></ul> <b>Offline-first</b>: UI đọc từ DB local; mọi thay đổi ghi vào local và vào một outbox; có mạng thì đẩy lên kèm idempotency key, kéo thay đổi mới về theo <code>updatedAt</code> hoặc cursor, rồi xử lý xung đột (last-write-wins hoặc theo version). Token không lưu ở những chỗ này mà ở Keychain/Keystore.", x:"Expense Tracker phải ghi được giao dịch khi đang ở nơi không có sóng. Giao dịch lưu trong SQLite kèm cột trạng thái đồng bộ (số tiền lưu số nguyên để tránh sai số float), còn settings để trong MMKV:<pre>const db = await SQLite.openDatabaseAsync('expense.db');\nawait db.execAsync(`CREATE TABLE IF NOT EXISTS tx (\n  id TEXT PRIMARY KEY, amount INTEGER NOT NULL, category TEXT,\n  updated_at INTEGER NOT NULL, sync_state TEXT DEFAULT 'pending')`);\n\nasync function addTxOffline(tx: Tx) {\n  await db.runAsync(\n    'INSERT INTO tx (id, amount, category, updated_at) VALUES (?, ?, ?, ?)',\n    tx.id, tx.amount, tx.category, Date.now()); // id là UUID tạo ở client\n  syncQueue.kick(); // có mạng thì đẩy các dòng pending lên, kèm idempotency key\n}</pre>"},
  "w3k8": {c:"GraphQL là ngôn ngữ truy vấn API cho phép client chỉ định chính xác các field cần lấy qua một endpoint; Apollo Client và urql là thư viện phía client lo gửi query, cache kết quả và cập nhật UI. Node.js là runtime JavaScript phía server, còn NestJS là framework Node có cấu trúc module và dependency injection.", e:"<ul><li><b>Query và mutation</b>: hook <code>useQuery(QUERY, { variables })</code>, <code>useMutation</code>; nên sinh type từ schema bằng GraphQL Code Generator.</li><li><b>Cache</b>: Apollo dùng normalized cache (<code>InMemoryCache</code>), tách từng object theo <code>__typename</code> + <code>id</code>, nên mutation trả về object có id sẽ tự cập nhật mọi màn đang hiển thị object đó; còn thêm hoặc xoá phần tử khỏi danh sách thì phải <code>cache.modify</code> hoặc <code>refetchQueries</code>. urql mặc định dùng document cache đơn giản (cache theo query, invalidate theo <code>__typename</code>), muốn normalized thì thêm Graphcache.</li><li><b>Pagination</b>: cursor theo chuẩn Relay connection (<code>edges</code>, <code>pageInfo.endCursor</code>, <code>hasNextPage</code>), gọi <code>fetchMore</code> và khai báo <code>typePolicies</code> để gộp các trang; tránh offset khi dữ liệu thay đổi liên tục.</li><li><b>Node/NestJS cơ bản</b>: hiểu event loop phía server, controller REST, guard/middleware kiểm tra JWT, DTO validate bằng <code>class-validator</code>, kết nối DB qua Prisma hoặc TypeORM; đủ để đọc code backend, viết một BFF nhỏ hoặc mock server.</li></ul>", x:"Màn “Giao dịch” cuộn vô hạn bằng Apollo với cursor; các trang được gộp ngay trong cache nên FlatList chỉ nhận một mảng:<pre>const TXS = gql`query Txs($after: String) {\n  transactions(first: 30, after: $after) {\n    edges { node { id amount note } }\n    pageInfo { endCursor hasNextPage }\n  } }`;\nconst cache = new InMemoryCache({ typePolicies: { Query: { fields: {\n  transactions: relayStylePagination(),   // gộp các trang theo cursor\n} } } });\n\nconst { data, fetchMore } = useQuery(TXS);\nconst onEndReached = () =&gt; {\n  const p = data?.transactions.pageInfo;\n  if (p?.hasNextPage) fetchMore({ variables: { after: p.endCursor } });\n};</pre>"},
  "w4k0": {c:"Interceptor là hàm chen vào mọi request hoặc response của HTTP client để xử lý chung (gắn token, log, chuẩn hoá lỗi). Bài toán refresh token song song là đảm bảo khi nhiều request cùng nhận 401 thì API refresh chỉ được gọi đúng một lần, các request còn lại chờ token mới rồi thử lại.", e:"Request interceptor đọc access token (giữ trong memory, nạp từ secure store lúc khởi động) và gắn header <code>Authorization</code>. Response interceptor bắt lỗi 401: nếu chưa có lần refresh nào đang chạy thì tạo một <code>refreshPromise</code> dùng chung, mọi request lỗi khác <code>await</code> chính promise đó rồi gửi lại với token mới. Đánh dấu request đã retry (<code>_retry</code>) để không lặp vô hạn, và loại trừ chính endpoint refresh. Refresh thất bại (refresh token hết hạn hoặc bị thu hồi) thì xoá token, logout và reject tất cả. Nếu server dùng refresh token rotation, hai lần refresh song song có thể bị coi là dùng lại token và làm server thu hồi cả phiên, nên “chỉ gọi một lần” là yêu cầu về đúng sai chứ không chỉ để tối ưu. Với <code>fetch</code> không có interceptor thì viết một hàm bọc <code>apiFetch</code> theo cùng logic. Có thể chủ động refresh trước khi hết hạn dựa trên <code>exp</code> của JWT để giảm số lần gặp 401.", x:"Mở app sau một đêm, màn Home bắn song song 4 request và cả 4 nhận 401. Bản cũ gọi refresh 4 lần; server dùng rotation nên coi 3 lần sau là dùng lại token và đăng xuất người dùng. Bản sửa với axios:<pre>let refreshPromise: Promise&lt;string&gt; | null = null;\n\napi.interceptors.response.use(undefined, async error =&gt; {\n  const original = error.config;\n  if (error.response?.status !== 401 || original._retry || original.url === '/auth/refresh')\n    throw error;\n  original._retry = true;\n  refreshPromise ??= refreshTokens()        // gọi API refresh, lưu token mới\n    .catch(e =&gt; { signOut(); throw e; })\n    .finally(() =&gt; { refreshPromise = null; });\n  const token = await refreshPromise;\n  original.headers.Authorization = `Bearer ${token}`;\n  return api(original);\n});</pre>"},
  "w4k1": {c:"Token đăng nhập phải được lưu trong kho bảo mật của hệ điều hành: Keychain trên iOS, và trên Android là dữ liệu được mã hoá bằng khoá nằm trong Android Keystore. <code>expo-secure-store</code> và <code>react-native-keychain</code> là các lớp bọc JS cho những kho này.", e:"AsyncStorage lưu plaintext trong sandbox của app; trên máy đã root hoặc jailbreak, qua bản backup hay công cụ debug, ai cũng đọc được, nên không được dùng cho access token, refresh token, mật khẩu. Keychain và Keystore dùng khoá do phần cứng bảo vệ, có thể đặt điều kiện truy cập: chỉ đọc khi máy đã mở khoá, biến thể <code>*_THIS_DEVICE_ONLY</code> để không đi theo bản backup sang máy khác, hoặc yêu cầu sinh trắc học (<code>requireAuthentication</code>; thêm vân tay mới sẽ làm khoá mất hiệu lực). Lưu ý: trên iOS, dữ liệu Keychain có thể còn lại sau khi gỡ và cài lại app, nên lần chạy đầu sau khi cài cần xoá token cũ; trên Android, nên loại dữ liệu secure store khỏi Auto Backup vì khôi phục sang máy khác sẽ không giải mã được. Một số bản iOS từng từ chối giá trị lớn hơn khoảng 2 KB, nên chỉ lưu token chứ không lưu cả profile. Khi chạy, giữ access token trong memory để không phải đọc secure store mỗi request. Kho bảo mật cũng vô ích nếu token bị log ra console hay gửi kèm lên Sentry.", x:"Đợt pentest báo cáo: trên máy Android đã root, đọc được refresh token trong file AsyncStorage của app. Chuyển token sang secure store, xoá key cũ khi migrate, và dọn token còn sót sau khi cài lại app trên iOS:<pre>import * as SecureStore from 'expo-secure-store';\n\nconst opts = { keychainAccessible: SecureStore.WHEN_UNLOCKED_THIS_DEVICE_ONLY };\nexport const tokenStore = {\n  save: (t: Tokens) =&gt; SecureStore.setItemAsync('tokens', JSON.stringify(t), opts),\n  load: async () =&gt; {\n    const raw = await SecureStore.getItemAsync('tokens', opts);\n    return raw ? (JSON.parse(raw) as Tokens) : null;\n  },\n  clear: () =&gt; SecureStore.deleteItemAsync('tokens', opts),\n};\n// Lần chạy đầu sau khi cài (chưa có cờ trong MMKV): gọi tokenStore.clear()\n// Migrate: đọc token từ AsyncStorage, lưu sang secure store, rồi removeItem key cũ</pre>"},
  "w4k2": {c:"WebSocket là kết nối hai chiều được giữ mở liên tục giữa app và server trên nền TCP, dùng cho dữ liệu realtime như chat, số dư, giá. Trên mobile, phần khó là giữ kết nối ổn định khi mạng chập chờn và khi app chuyển xuống background.", e:"<ul><li><b>Reconnect với backoff</b>: khi kết nối đóng bất thường, thử lại sau 1s, 2s, 4s... có giới hạn trên (ví dụ 30s) và thêm <b>jitter</b> ngẫu nhiên để hàng nghìn client không cùng lúc dội vào server sau sự cố; reset bộ đếm khi kết nối thành công; không reconnect khi chủ động đóng (logout).</li><li><b>Heartbeat</b>: gửi ping định kỳ, quá hạn mà không nhận được pong thì coi kết nối đã chết, đóng và kết nối lại; mạng di động hay làm kết nối “treo” mà không phát sự kiện <code>close</code>.</li><li><b>Background</b>: iOS tạm dừng app sau vài giây ở background nên socket sẽ chết; Android cũng hạn chế (Doze, giới hạn chạy nền). Cách đúng là chủ động đóng khi vào background, mở lại khi app <code>active</code>, rồi refetch qua REST hoặc gửi <code>lastEventId</code> để lấp khoảng trống; khi app không chạy thì dựa vào push notification.</li></ul> Thêm: nghe NetInfo để kết nối lại ngay khi có mạng, xác thực khi connect và xử lý token hết hạn, dedupe message theo id, xếp hàng các tin gửi đi trong lúc mất kết nối.", x:"Màn số dư realtime: sau khi người dùng đi qua hầm, số dư đứng im vì socket “sống giả”. Thêm heartbeat, backoff có jitter, và đồng bộ lại khi quay về foreground (WebSocket của RN nhận thêm tham số thứ ba để gắn header):<pre>function connect(attempt = 0) {\n  const ws = new WebSocket(WS_URL, undefined, { headers: { Authorization: `Bearer ${token}` } });\n  let ping: ReturnType&lt;typeof setInterval&gt;;\n  ws.onopen = () =&gt; {\n    attempt = 0;\n    ping = setInterval(() =&gt; ws.send(JSON.stringify({ type: 'ping' })), 25000);\n  };\n  ws.onmessage = e =&gt; handle(JSON.parse(e.data)); // pong: cập nhật lastPong, quá 60s thì ws.close()\n  ws.onclose = () =&gt; {\n    clearInterval(ping);\n    if (manualClose) return;\n    const delay = Math.min(30000, 1000 * 2 ** attempt) * (0.5 + Math.random() / 2);\n    setTimeout(() =&gt; connect(attempt + 1), delay);\n  };\n}</pre> Kèm theo: khi AppState chuyển sang <code>background</code> thì đặt <code>manualClose = true</code> và <code>ws.close()</code>; khi về <code>active</code> thì <code>connect()</code> lại và refetch số dư qua REST."},
  "w4k3": {c:"Push notification là thông báo do server gửi qua dịch vụ của nền tảng, FCM (Firebase Cloud Messaging) cho Android và APNs (Apple Push Notification service) cho iOS, tới thiết bị được định danh bằng push token.", e:"<ul><li><b>Token</b>: app xin quyền (iOS luôn cần; Android 13 trở lên cần quyền <code>POST_NOTIFICATIONS</code>), lấy token rồi gửi lên backend gắn với user. Token có thể đổi (cài lại app, khôi phục máy) nên phải nghe sự kiện token mới và cập nhật; logout thì gỡ token khỏi user. Expo push token đi qua dịch vụ trung gian của Expo; muốn gửi trực tiếp thì dùng device token của FCM/APNs.</li><li><b>Foreground</b>: app nhận message qua listener và tự quyết định có hiện banner không (với expo-notifications là <code>setNotificationHandler</code>).</li><li><b>Background</b>: OS hiện notification; khi người dùng bấm vào, app nhận sự kiện response và điều hướng.</li><li><b>Killed</b>: OS hiện notification; khi bấm, app khởi động lạnh và phải đọc notification đã mở app (<code>useLastNotificationResponse</code> hoặc <code>getLastNotificationResponseAsync</code>) sau khi navigation sẵn sàng.</li></ul> Android cần <b>notification channel</b> (người dùng chỉnh âm thanh, mức ưu tiên theo channel). Silent/data-only push trên iOS không được đảm bảo giao và bị giới hạn tần suất; Android force-stop thì không nhận được tới khi mở lại app. Thư viện: <code>expo-notifications</code> (cần development build, Expo Go không hỗ trợ push); <code>notifee</code> đã bị Invertase archive từ 04/2026, dự án mới nên dùng expo-notifications hoặc fork đang được duy trì.", x:"Push “Bạn đã dùng 80% ngân sách Ăn uống” phải mở đúng màn ngân sách ở cả ba trạng thái app. Lỗi hay gặp: khi app đã bị tắt, bấm vào notification chỉ mở Home, vì listener được đăng ký sau khi sự kiện đã xảy ra.<pre>Notifications.setNotificationHandler({\n  handleNotification: async () =&gt; ({\n    shouldShowBanner: true, shouldShowList: true,\n    shouldPlaySound: false, shouldSetBadge: false }),\n});\n\nfunction usePushNavigation() {\n  const last = Notifications.useLastNotificationResponse(); // gồm cả lúc cold start\n  useEffect(() =&gt; {\n    const url = last?.notification.request.content.data?.url;\n    if (typeof url === 'string') router.push(url); // ví dụ '/budget/food'\n  }, [last]);\n}\n// Android: tạo channel trước khi xin token\n// Notifications.setNotificationChannelAsync('budget', { name: 'Ngân sách', importance: Notifications.AndroidImportance.HIGH })</pre>"},
  "w4k4": {c:"Firebase là nền tảng của Google cung cấp nhiều dịch vụ cho app; ba dịch vụ hay gặp trong JD mobile là Analytics (đo hành vi người dùng qua event), Crashlytics (thu thập crash) và Remote Config (đổi cấu hình, feature flag từ server mà không cần phát hành bản mới).", e:"Trên RN thường dùng React Native Firebase (<code>@react-native-firebase/*</code>). Đây là native SDK nên với Expo cần development build và config plugin, cùng file <code>google-services.json</code> và <code>GoogleService-Info.plist</code>. Bản mới dùng <b>modular API</b> giống Firebase JS SDK (<code>getAnalytics()</code>, <code>logEvent(...)</code>), API dạng namespace cũ đã bị deprecate và gỡ dần.<ul><li><b>Analytics</b>: đặt tên event theo quy ước (<code>add_transaction</code>), số lượng và độ dài tham số có giới hạn; <code>setUserId</code> và user property để phân nhóm; ghi screen view khi đổi màn; không gửi PII và tôn trọng consent của người dùng.</li><li><b>Crashlytics</b>: bắt crash native và lỗi JS gửi qua <code>recordError</code>; cần upload dSYM (iOS) và mapping R8 (Android) để đọc được stack; <code>log()</code> để ghi lại các bước trước crash; theo dõi tỉ lệ crash-free users theo phiên bản.</li><li><b>Remote Config</b>: đặt giá trị mặc định trong app, gọi <code>fetchAndActivate</code> lúc khởi động; dữ liệu có cache (<code>minimumFetchIntervalMillis</code>) nên không dùng cho thứ cần tức thời; giá trị mới thường áp dụng từ lần mở sau để UI không đổi giữa chừng. Hợp với feature flag, kill switch, A/B test, phiên bản tối thiểu bắt buộc cập nhật.</li></ul>", x:"Product muốn thử nút “Quét hoá đơn” cho 20% người dùng và đo tỉ lệ sử dụng. Remote Config giữ cờ (điều kiện 20% cấu hình trên console), Analytics đo event, Crashlytics theo dõi xem tính năng mới có làm tăng crash không:<pre>import { getRemoteConfig, setDefaults, fetchAndActivate, getValue } from '@react-native-firebase/remote-config';\nimport { getAnalytics, logEvent } from '@react-native-firebase/analytics';\n\nconst rc = getRemoteConfig();\nawait setDefaults(rc, { scan_receipt_enabled: false, min_supported_version: '1.0.0' });\nawait fetchAndActivate(rc);\nconst showScan = getValue(rc, 'scan_receipt_enabled').asBoolean();\n\n// Khi người dùng dùng tính năng\nawait logEvent(getAnalytics(), 'scan_receipt', { source: 'home_button' });</pre>"},
  "w4k5": {c:"<code>AppState</code> là API của React Native cho biết app đang <code>active</code>, <code>background</code> hay <code>inactive</code> (chỉ có trên iOS) và phát sự kiện khi trạng thái đổi; NetInfo (<code>@react-native-community/netinfo</code>) cho biết loại kết nối mạng và khả năng truy cập Internet.", e:"<code>AppState.addEventListener('change', fn)</code> trả về một subscription, phải gọi <code>.remove()</code> trong cleanup. Các tình huống dùng: refetch dữ liệu và mở lại socket khi quay về <code>active</code>; khoá app bằng sinh trắc học sau khi ở background quá N phút; che nội dung nhạy cảm trong màn đa nhiệm (trạng thái <code>inactive</code> trên iOS); lưu nháp khi rời app. NetInfo trả về <code>isConnected</code> (có kết nối tới một mạng) và <code>isInternetReachable</code> (đã thử tới Internet thật, có thể là <code>null</code> lúc đầu); Wi-Fi có captive portal thì <code>isConnected</code> vẫn là true. <b>Xử lý mất mạng</b>: hiện banner offline thay cho lỗi chung chung; với TanStack Query thì nối <code>onlineManager</code> để tạm dừng query/mutation và tự chạy lại khi có mạng; ghi thao tác vào outbox; retry có backoff và timeout; phân biệt lỗi mạng với lỗi 4xx/5xx để hiện thông điệp đúng. Đừng chặn request chỉ vì NetInfo báo offline, vì nó có thể sai; cứ thử và xử lý lỗi.", x:"Người dùng mở app trong thang máy: màn Home quay spinner mãi rồi báo “Đã có lỗi”. Bản sửa nối NetInfo và AppState vào TanStack Query, hiện banner offline, và tự tải lại khi có mạng hoặc khi quay lại app:<pre>onlineManager.setEventListener(setOnline =&gt;\n  NetInfo.addEventListener(state =&gt; setOnline(!!state.isConnected)));\n\nfunction useAppFocus() {\n  useEffect(() =&gt; {\n    const sub = AppState.addEventListener('change', s =&gt;\n      focusManager.setFocused(s === 'active'));\n    return () =&gt; sub.remove();\n  }, []);\n}\n\nfunction OfflineBanner() {\n  const { isConnected } = useNetInfo();\n  return isConnected === false ? &lt;Banner text='Đang offline, dữ liệu có thể chưa mới' /&gt; : null;\n}</pre>"},
  "w4k6": {c:"i18n (internationalization) là việc chuẩn bị app để hiển thị được nhiều ngôn ngữ và quy ước vùng miền: chuỗi dịch, số nhiều, định dạng tiền tệ, số, ngày giờ, và hướng viết.", e:"Chuỗi giao diện đưa vào file dịch theo key, thường dùng <code>i18next</code> + <code>react-i18next</code>, kết hợp <code>expo-localization</code> để biết ngôn ngữ của máy. Không ghép chuỗi bằng <code>+</code> vì thứ tự từ khác nhau giữa các ngôn ngữ; dùng interpolation và quy tắc số nhiều (plural). Định dạng nên dùng <code>Intl</code> (Hermes hỗ trợ <code>Intl.NumberFormat</code>, <code>Intl.DateTimeFormat</code>) thay vì tự viết: <code>vi-VN</code> với VND cho ra dạng <code>150.000 ₫</code>, còn JPY không có phần thập phân. Tiền nên lưu dạng số nguyên theo đơn vị nhỏ nhất (đồng, cent) chứ không dùng float. Ngày giờ lưu dạng UTC/ISO 8601 ở server và chỉ đổi sang múi giờ của người dùng khi hiển thị; cẩn thận với <code>new Date('2026-10-15')</code>, chuỗi chỉ có ngày được hiểu là nửa đêm UTC nên ở múi giờ âm sẽ hiện thành ngày hôm trước. Tạo formatter một lần rồi dùng lại vì khởi tạo <code>Intl</code> khá tốn kém, và chừa chỗ trong layout cho ngôn ngữ có chuỗi dài.", x:"Khi mở thị trường Nhật, số tiền hiện thành <code>¥1,500.00</code> vì code cũ tự ghép ký hiệu và luôn để 2 chữ số thập phân. Dùng <code>Intl</code> theo tiền tệ của ví, có cache formatter:<pre>const cache = new Map&lt;string, Intl.NumberFormat&gt;();\nexport function formatMoney(minor: number, currency: string, locale: string) {\n  const key = `${locale}-${currency}`;\n  let f = cache.get(key);\n  if (!f) cache.set(key, (f = new Intl.NumberFormat(locale, { style: 'currency', currency })));\n  const digits = f.resolvedOptions().maximumFractionDigits ?? 0;\n  return f.format(minor / 10 ** digits); // lưu số nguyên theo đơn vị nhỏ nhất\n}\nformatMoney(150000, 'VND', 'vi-VN'); // '150.000 ₫'\nformatMoney(1500, 'JPY', 'ja-JP');   // '￥1,500'\nformatMoney(1999, 'USD', 'en-US');   // '$19.99'\n\nt('tx.count', { count: 3 }); // i18next chọn key 'tx.count_one' hoặc 'tx.count_other'</pre>"},
  "w4k7": {c:"Bảo mật app RN ở phía client gồm nhiều lớp: SSL pinning để chống tấn công man-in-the-middle, obfuscation để làm khó việc dịch ngược, và nguyên tắc không đặt bí mật trong JS bundle, vì mọi thứ nằm trong app đều có thể bị trích xuất.", e:"<ul><li><b>SSL pinning</b>: app chỉ chấp nhận chứng chỉ của server mình (nên pin hash public key SPKI) thay vì tin mọi CA của hệ thống, nhờ đó chặn được proxy như Charles hay mitmproxy. Phải có pin dự phòng và kế hoạch xoay khoá; nếu không, khi đổi chứng chỉ toàn bộ app mất kết nối và chỉ sửa được bằng bản build mới. Thư viện như <code>react-native-ssl-public-key-pinning</code>; Android còn có thể khai báo trong <code>network_security_config.xml</code>.</li><li><b>Obfuscation</b>: bật R8/ProGuard cho code Java/Kotlin (nhớ keep rule cho class dùng qua reflection). Hermes bytecode khó đọc hơn JS thuần nhưng <b>không</b> phải mã hoá, vẫn có công cụ dịch ngược. Obfuscation chỉ làm chậm kẻ tấn công.</li><li><b>Không để secret trong bundle</b>: biến <code>EXPO_PUBLIC_*</code> hay <code>.env</code> nhúng qua babel đều nằm nguyên trong bundle. API key của dịch vụ trả phí, secret ký JWT, khoá của bên thứ ba phải ở backend (BFF/proxy); key bắt buộc có ở client (Maps, Firebase) thì giới hạn theo package name, bundle ID và SHA.</li></ul> Thêm: kiểm tra root/jailbreak với app tài chính, tắt log nhạy cảm ở bản release, và dẫn chiếu OWASP MASVS khi được hỏi về bảo mật tổng thể.", x:"Audit phát hiện khoá của dịch vụ OCR bên thứ ba nằm trong <code>.env</code> và được build vào bundle: giải nén APK, đọc file bundle là lấy được, hoá đơn dịch vụ tháng sau tăng vọt. Cách sửa: chuyển việc gọi OCR qua backend có xác thực user và rate limit, thu hồi khoá cũ. Đồng thời bật pinning cho domain API (thư viện yêu cầu ít nhất 2 hash trên iOS, nên luôn có khoá dự phòng):<pre>import { initializeSslPinning } from 'react-native-ssl-public-key-pinning';\n\nawait initializeSslPinning({\n  'api.expensetracker.app': {\n    includeSubdomains: true,\n    publicKeyHashes: [\n      'BASE64_SPKI_SHA256_CUA_KHOA_HIEN_TAI=',\n      'BASE64_SPKI_SHA256_CUA_KHOA_DU_PHONG=',\n    ],\n  },\n});\n// Sai: const OCR_KEY = process.env.EXPO_PUBLIC_OCR_KEY; ai cũng đọc được trong bundle</pre>"},
  "w5k0": {c:"Một app React Native chạy trên nhiều thread: JS thread chạy JavaScript và React, UI (main) thread vẽ view native và nhận sự kiện chạm, cùng các background thread cho layout, native module và I/O. Hermes là JavaScript engine do Meta phát triển và là engine mặc định của RN.", e:"<ul><li><b>JS thread</b>: chạy bundle, render React, xử lý logic. Bị chặn thì tap phản hồi chậm, JS FPS tụt, nhưng animation chạy native vẫn mượt.</li><li><b>UI thread</b>: thread duy nhất được phép chạm vào view native (UIKit, Android View), xử lý gesture và animation native. Bị chặn bởi code native nặng thì cả app đơ, trên Android có thể sinh ANR.</li><li><b>Background thread</b>: với Fabric, layout (Yoga) và việc dựng shadow tree có thể chạy ngoài main thread; native module chạy trên thread hoặc queue riêng, ví dụ <code>AsyncFunction</code> của Expo Modules mặc định không chạy trên main thread.</li><li><b>Hermes</b>: biên dịch JS sang bytecode ngay lúc build (AOT), nên khi mở app không phải parse và compile JS, startup nhanh hơn và tốn ít RAM hơn; GC được tối ưu cho mobile; debug qua React Native DevTools (giao thức Chrome DevTools). Hermes không có JIT như V8, nên code tính toán nặng chạy lâu có thể chậm hơn engine có JIT; đổi lại khởi động nhanh, phù hợp mobile.</li></ul>", x:"Câu hỏi phỏng vấn: “Màn A cuộn mượt nhưng bấm nút Lọc 1 giây sau mới phản hồi; màn B thì cuộn cũng giật. Chẩn đoán thế nào?” Bật Perf Monitor: ở màn A, JS FPS tụt còn UI FPS ổn, tức JS thread đang bận (lọc 10.000 item đồng bộ, render lại cả list). Ở màn B, UI FPS tụt, thường do cây view quá phức tạp, ảnh quá lớn phải decode, hoặc native module làm việc nặng trên main thread. Với native module, giữ việc nặng ngoài main thread:<pre>// Expo Modules (Kotlin)\nAsyncFunction(\"exportCsv\") { path: String -&gt;\n  writeCsv(path)            // I/O nặng, mặc định không chạy trên main thread\n}\n\n// Chỉ khi buộc phải thao tác UI mới chỉ định main queue\nAsyncFunction(\"showNativeSheet\") {\n  presentSheet()\n}.runOnQueue(Queues.MAIN)</pre>"},
  "w5k1": {c:"Bridge là cơ chế giao tiếp giữa JS và native của kiến trúc cũ, gửi message JSON bất đồng bộ qua một hàng đợi. JSI (JavaScript Interface) là API C++ cho phép JavaScript giữ tham chiếu trực tiếp tới object C++ (host object) và gọi hàm native đồng bộ mà không cần serialize.", e:"Với bridge, mỗi lời gọi phải chuyển tham số thành JSON, đưa vào hàng đợi, gộp thành lô rồi gửi sang native, native lại parse JSON; kết quả trả về cũng theo cách đó. Hệ quả: mọi lời gọi đều bất đồng bộ (không thể đọc layout hay một giá trị native ngay lập tức), chi phí serialize lớn với dữ liệu nhiều (ảnh, buffer, danh sách dài), và bridge dễ nghẽn khi event dồn dập (scroll, gesture), làm UI trễ so với ngón tay. Mọi native module cũng phải khởi tạo ngay khi app mở. JSI bỏ lớp trung gian đó: engine (Hermes) và C++ dùng chung bộ nhớ, JS gọi host function như hàm thường, có thể đồng bộ hoặc trả Promise, truyền <code>ArrayBuffer</code> không phải copy. Đồng bộ không phải lúc nào cũng tốt: gọi đồng bộ một hàm native chậm sẽ chặn JS thread, nên việc nặng vẫn nên async. JSI là nền của TurboModules, Fabric và nhiều thư viện hiệu năng cao như Reanimated, MMKV, VisionCamera, Nitro Modules.", x:"So sánh khi đọc một cài đặt lúc khởi động. AsyncStorage được thiết kế từ thời bridge nên phải chờ Promise, màn đầu nháy theme sáng rồi mới đổi sang tối. MMKV đi qua JSI nên đọc đồng bộ ngay trong lần render đầu:<pre>// Kiểu bridge: bất đồng bộ, lần render đầu chưa có giá trị\nconst [theme, setTheme] = useState&lt;'light' | 'dark'&gt;('light');\nuseEffect(() =&gt; {\n  AsyncStorage.getItem('theme').then(v =&gt; v &amp;&amp; setTheme(v as 'light' | 'dark'));\n}, []);\n\n// JSI: host object, gọi đồng bộ, không serialize\nconst storage = createMMKV();\nconst initialTheme = storage.getString('theme') ?? 'light';</pre> Khi trả lời phỏng vấn, nên kết bằng tác động thực tế: startup nhanh hơn, gesture và animation không còn trễ vì nghẽn bridge, và có API đồng bộ như đo layout trước khi vẽ."},
  "w5k2": {c:"Đây là các thành phần của New Architecture: Fabric là renderer mới viết bằng C++, TurboModules là thế hệ native module mới gọi qua JSI và được nạp lười, Codegen sinh code native có kiểu chặt từ spec TypeScript, còn bridgeless mode là chế độ chạy hoàn toàn không khởi tạo bridge cũ.", e:"<ul><li><b>Fabric</b>: shadow tree và layout (Yoga) nằm trong lớp C++ dùng chung cho iOS và Android; hỗ trợ concurrent React (transition, Suspense, render có thể bị ngắt); cho phép đo và cập nhật layout đồng bộ trong <code>useLayoutEffect</code> nên không còn hiện tượng nháy layout.</li><li><b>TurboModules</b>: module chỉ được khởi tạo khi JS dùng tới lần đầu (lazy) thay vì khởi tạo tất cả lúc startup; gọi trực tiếp qua JSI, hỗ trợ cả hàm đồng bộ.</li><li><b>Codegen</b>: đọc file spec (<code>NativeXxx.ts</code> cho module, <code>XxxNativeComponent.ts</code> cho view) để sinh interface C++/Objective-C/Java mà phần native phải implement; lệch kiểu giữa JS và native bị phát hiện lúc build thay vì crash lúc chạy.</li><li><b>Bridgeless mode</b>: bỏ hẳn bridge, kể cả cho timer, event emitter, xử lý lỗi; được bật mặc định cùng New Architecture từ RN 0.74.</li></ul> Các thư viện viết cho kiến trúc cũ vẫn chạy được phần lớn nhờ <b>interop layer</b>, nhưng không đảm bảo đúng trong mọi trường hợp, nên vẫn cần kiểm tra từng thư viện.", x:"Viết spec Turbo Module cho chức năng đọc mức pin. Codegen sinh <code>NativeBatterySpec</code> cho Android và iOS; native implement sai kiểu là build lỗi ngay:<pre>// specs/NativeBattery.ts\nimport type { TurboModule } from 'react-native';\nimport { TurboModuleRegistry } from 'react-native';\n\nexport interface Spec extends TurboModule {\n  getLevel(): number;               // đồng bộ qua JSI\n  isCharging(): Promise&lt;boolean&gt;;\n}\nexport default TurboModuleRegistry.getEnforcing&lt;Spec&gt;('NativeBattery');\n\n// package.json\n// \"codegenConfig\": { \"name\": \"NativeBatterySpec\", \"type\": \"modules\",\n//   \"jsSrcsDir\": \"specs\", \"android\": { \"javaPackageName\": \"com.expense.battery\" } }</pre>"},
  "w5k3": {c:"New Architecture (JSI, Fabric, TurboModules, bridgeless) trở thành mặc định cho mọi project từ React Native 0.76 (10/2024); từ RN 0.82 (10/2025), app luôn chạy trên New Architecture và không thể tắt được nữa.", e:"Các mốc chính:<ul><li>0.68: cho phép bật New Architecture ở dạng thử nghiệm.</li><li>0.74: bridgeless trở thành mặc định khi bật New Architecture.</li><li>0.76: New Architecture bật mặc định cho mọi app.</li><li>0.80: Legacy Architecture bị đóng băng, kèm cảnh báo khi dùng API cũ; 0.81 (cùng Expo SDK 54) là những bản cuối còn cho dùng Legacy Architecture.</li><li>0.82: cờ <code>newArchEnabled=false</code> (Android) và <code>RCT_NEW_ARCH_ENABLED=0</code> (iOS) bị bỏ qua; API legacy bắt đầu được gỡ khỏi core từ các bản sau.</li></ul> Hệ quả thực tế: thư viện chỉ hỗ trợ kiến trúc cũ sẽ hỏng hoặc phải trông vào interop layer; nhiều thư viện lớn như Reanimated 4, FlashList v2 đã chỉ hướng tới New Architecture, nên trước khi nâng cấp phải kiểm từng dependency trên React Native Directory. Khi phỏng vấn, nên nói được cả lợi ích (startup, layout đồng bộ, concurrent React) lẫn chi phí migrate (thư viện cũ, native module tự viết phải chuyển sang Turbo Module hoặc Expo Modules).", x:"Câu hỏi: “App đang ở RN 0.73 với 60 dependency, cần lên bản mới nhất. Bạn đánh giá rủi ro New Architecture thế nào?” Trả lời có cấu trúc: (1) dừng ở một bản còn cho tắt New Architecture (0.76 tới 0.81), bật nó lên để tách rủi ro kiến trúc khỏi rủi ro nâng cấp; (2) liệt kê thư viện native, tra React Native Directory, thay các thư viện đã bỏ hoang; (3) chuyển native module tự viết sang Turbo Module hoặc Expo Modules; (4) test kỹ các màn dùng nhiều view native (map, video, webview); (5) ổn định rồi mới nâng tiếp lên 0.82 trở đi, nơi không còn đường lui.<pre># android/gradle.properties (chỉ còn tác dụng tới 0.81)\nnewArchEnabled=true\n\n# iOS (tới 0.81)\nRCT_NEW_ARCH_ENABLED=1 bundle exec pod install\n\n# Expo (tới SDK 54): app.json, \"newArchEnabled\": true (mặc định từ SDK 53)</pre>"},
  "w5k4": {c:"Native module là phần code Kotlin/Swift (hoặc Java, Objective-C, C++) đưa API của hệ điều hành hay SDK native ra cho JavaScript gọi. Hiện có hai cách viết chính: Expo Modules API và Turbo Module kết hợp Codegen.", e:"<b>Expo Modules API</b>: khai báo bằng DSL <code>ModuleDefinition</code> (<code>Name</code>, <code>Function</code> cho hàm đồng bộ, <code>AsyncFunction</code> trả Promise, <code>Events</code>, <code>Constants</code>, <code>OnCreate</code>/<code>OnDestroy</code>), tự chuyển đổi kiểu giữa Kotlin/Swift và JS, dùng được cả trong app bare có cài <code>expo</code>; tạo khung nhanh bằng <code>npx create-expo-module --local</code>. <b>Turbo Module</b>: viết spec TypeScript, Codegen sinh interface, sau đó implement bằng Kotlin (kế thừa class <code>NativeXxxSpec</code> được sinh) và Objective-C++/Swift trên iOS; hợp khi viết thư viện không phụ thuộc Expo hoặc cần dùng chung code C++. Lưu ý chung:<ul><li>Việc nặng không chạy trên main thread.</li><li>Tham số và kết quả phải là kiểu chuyển đổi được (số, chuỗi, map, record).</li><li>Lỗi nên reject với mã lỗi rõ ràng (<code>CodedException</code> trong Expo) để JS bắt và xử lý.</li><li>Xin permission đúng cách và khai báo trong <code>AndroidManifest.xml</code>, <code>Info.plist</code> (thường qua config plugin).</li><li>Viết type TS cho phía JS và mock module trong Jest.</li></ul>", x:"Lab “BatteryInfo” của tuần này: module trả về % pin và phát event khi trạng thái sạc thay đổi. Phần Kotlin bên dưới; <code>registerChargingReceiver</code> là hàm phụ tự viết, đăng ký BroadcastReceiver cho <code>ACTION_POWER_CONNECTED</code> và <code>ACTION_POWER_DISCONNECTED</code>. Phía Swift tương tự, dùng <code>UIDevice.current.batteryLevel</code> sau khi bật <code>isBatteryMonitoringEnabled</code>:<pre>class BatteryInfoModule : Module() {\n  override fun definition() = ModuleDefinition {\n    Name(\"BatteryInfo\")\n    Events(\"onChargingChange\")\n    Function(\"getLevel\") {\n      val bm = appContext.reactContext?.getSystemService(Context.BATTERY_SERVICE) as? BatteryManager\n      bm?.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY) ?: -1\n    }\n    OnStartObserving { registerChargingReceiver { charging -&gt;\n      sendEvent(\"onChargingChange\", mapOf(\"charging\" to charging)) } }\n    OnStopObserving { unregisterChargingReceiver() }\n  }\n}\n// JS: const Battery = requireNativeModule('BatteryInfo'); Battery.getLevel();</pre>"},
  "w5k5": {c:"Native UI component là view native (Kotlin/Swift) được bọc thành component React để dùng trong JSX: nhận props từ JS và phát event ngược lên JS. Ví dụ: MapView, trình phát video, khung xem camera.", e:"Với <b>Expo Modules API</b>: trong <code>ModuleDefinition</code> khai báo <code>View(MyView::class) { Prop(...); Events(...) }</code>; class view kế thừa <code>ExpoView</code>, event khai báo bằng <code>EventDispatcher</code> rồi gọi như một hàm; phía JS lấy component bằng <code>requireNativeView</code> và đọc payload trong <code>event.nativeEvent</code>. Với <b>Fabric thuần</b>: viết spec <code>codegenNativeComponent&lt;NativeProps&gt;('MyView')</code>, props dùng kiểu của Codegen (<code>Int32</code>, <code>Double</code>, <code>DirectEventHandler</code>...), rồi implement view manager trên Android và component view trên iOS. Event lên JS có hai dạng: event gắn với một view cụ thể (prop <code>onXxx</code>, như <code>onRegionChange</code>) và event của cả module (<code>sendEvent</code> kết hợp <code>addListener</code>, như thay đổi trạng thái pin). Lưu ý: event dồn dập (scroll, từng khung hình camera) nên throttle hoặc xử lý luôn ở native/worklet để không làm ngập JS thread; huỷ listener native khi view bị gỡ; muốn ra lệnh cho view (play, seek) thì dùng hàm của view qua ref, thay vì liên tục đổi prop.", x:"Màn “Quét hoá đơn” cần một view camera native có khung căn và báo về JS khi phát hiện đủ 4 góc hoá đơn. Phần Swift với Expo Modules:<pre>public class ReceiptScannerModule: Module {\n  public func definition() -&gt; ModuleDefinition {\n    Name(\"ReceiptScanner\")\n    View(ScannerView.self) {\n      Events(\"onDetected\")\n      Prop(\"torch\") { (view: ScannerView, on: Bool) in view.setTorch(on) }\n    }\n  }\n}\nclass ScannerView: ExpoView {\n  let onDetected = EventDispatcher()\n  func didFindCorners(_ c: [CGPoint]) { onDetected([\"corners\": c.map { [$0.x, $0.y] }]) }\n}\n// JS: const Scanner = requireNativeView('ReceiptScanner');\n// &lt;Scanner torch={flash} onDetected={e =&gt; setCorners(e.nativeEvent.corners)} /&gt;</pre> Phát hiện góc chạy ở native, chỉ gửi event khi kết quả thay đổi, không gửi theo từng khung hình."},
  "w5k6": {c:"Expo prebuild (Continuous Native Generation, CNG) là bước sinh thư mục <code>android/</code> và <code>ios/</code> từ <code>app.json</code>/<code>app.config.ts</code> và các config plugin. Development build (dev client) là bản app debug chứa native code riêng của dự án, dùng thay Expo Go khi cần thư viện native nằm ngoài bộ có sẵn.", e:"<ul><li><b>Prebuild/CNG</b>: thư mục native được coi là sản phẩm sinh ra, có thể không cần commit; muốn đổi native thì sửa cấu hình hoặc plugin rồi chạy <code>npx expo prebuild --clean</code>. Nhờ vậy nâng SDK dễ hơn nhiều so với sửa tay.</li><li><b>Config plugin</b>: hàm chạy lúc prebuild để chỉnh AndroidManifest, Info.plist, Gradle, Podfile, entitlements (<code>withAndroidManifest</code>, <code>withInfoPlist</code>...); nhiều thư viện native kèm sẵn plugin.</li><li><b>Dev client</b>: cài <code>expo-dev-client</code>, build bằng <code>eas build --profile development</code> hoặc <code>npx expo run:android</code>; vẫn có Fast Refresh và tải JS từ Metro. Expo Go chỉ hợp để thử nhanh vì không thêm được native code.</li><li><b>Bare và managed</b>: ngày nay “managed” nghĩa là dùng CNG (không sửa tay thư mục native), “bare” là commit và tự quản lý <code>android/</code>, <code>ios/</code>; cả hai vẫn dùng được Expo SDK và EAS. Chọn bare khi native đã chỉnh sâu mà không viết được plugin, hoặc khi nhúng RN vào app native có sẵn (brownfield).</li></ul> Tài liệu React Native hiện khuyến nghị dùng framework, mà Expo là lựa chọn chính, khi tạo dự án mới.", x:"Lab tuần này: thêm quyền camera cho tính năng quét hoá đơn trên cả hai nền tảng mà không phải mở Android Studio hay Xcode. Viết config plugin cục bộ rồi khai báo trong <code>app.json</code> (<code>plugins: ['./plugins/withReceiptCamera']</code>), sau đó chạy <code>npx expo prebuild --clean</code>:<pre>// plugins/withReceiptCamera.js\nconst { withAndroidManifest, withInfoPlist, AndroidConfig } = require('expo/config-plugins');\n\nmodule.exports = function withReceiptCamera(config) {\n  config = withAndroidManifest(config, cfg =&gt; {\n    AndroidConfig.Permissions.ensurePermissions(cfg.modResults, ['android.permission.CAMERA']);\n    return cfg;\n  });\n  return withInfoPlist(config, cfg =&gt; {\n    cfg.modResults.NSCameraUsageDescription = 'Dùng camera để chụp hoá đơn';\n    return cfg;\n  });\n};</pre>"},
  "w5k7": {c:"Gradle là hệ thống build của Android; CocoaPods là trình quản lý dependency native cho iOS mà React Native dùng để liên kết thư viện; signing là việc ký số bản build để hệ điều hành và store xác nhận nguồn gốc; crash log native là báo cáo hệ thống tạo ra khi code Kotlin/Java/Swift/C++ làm app chết.", e:"<ul><li><b>Gradle</b>: <code>app/build.gradle</code> khai báo <code>compileSdk</code>, <code>targetSdk</code>, <code>minSdk</code>, <code>buildTypes</code>, <code>productFlavors</code>; <code>gradle.properties</code> chứa cờ như <code>hermesEnabled</code>. Lỗi hay gặp: lệch phiên bản Kotlin, AGP, JDK, hoặc cache hỏng (<code>./gradlew clean</code>).</li><li><b>CocoaPods</b>: <code>pod install</code> đọc <code>Podfile</code> và <code>Podfile.lock</code>; luôn mở <code>.xcworkspace</code> chứ không mở <code>.xcodeproj</code>; lệch phiên bản pod thì chạy <code>pod install --repo-update</code>.</li><li><b>Signing</b>: Android ký bằng keystore; iOS cần certificate và provisioning profile khớp bundle ID và entitlements.</li><li><b>Crash log</b>: Android xem <code>adb logcat</code> (tìm <code>FATAL EXCEPTION</code>); crash C++ tạo tombstone, symbolicate bằng <code>ndk-stack</code>; bản release bị R8 đổi tên nên cần <code>mapping.txt</code>. iOS lấy crash report (<code>.ips</code>) từ Xcode Organizer, symbolicate bằng dSYM, đọc <code>Exception Type</code> (<code>EXC_BAD_ACCESS</code>, <code>SIGABRT</code>) và thread bị crash.</li></ul> Với RN, lỗi JS không được bắt cũng có thể hiện thành crash native (<code>JavascriptException</code> trên Android, <code>RCTFatal</code> trên iOS), nên luôn đọc kèm phần JS stack trong message.", x:"Bản release Android crash ngay khi mở, còn bản debug thì không. Quy trình điều tra:<pre># 1. Lấy log trên máy test\nadb logcat -b crash\nadb logcat | grep -E 'AndroidRuntime|FATAL|ReactNativeJS'\n\n# 2. Ví dụ đọc được:\n# java.lang.ClassNotFoundException: com.expense.ocr.ReceiptParser\n#   nghĩa là R8 đã xoá class chỉ được dùng qua reflection\n\n# 3. Thêm keep rule vào android/app/proguard-rules.pro (Expo: expo-build-properties)\n-keep class com.expense.ocr.** { *; }\n\n# 4. Đổi tên trong stack trace bản release về tên gốc bằng mapping.txt\nretrace mapping.txt stacktrace.txt</pre>"},
  "w5k8": {c:"Nâng cấp React Native hay Expo SDK là đưa dự án lên phiên bản framework mới, bao gồm cả phần JS (các package), phần native (Gradle, Podfile, AppDelegate, MainApplication) và toàn bộ thư viện phụ thuộc.", e:"<ul><li><b>Upgrade Helper</b> (react-native-community.github.io/upgrade-helper): chọn phiên bản hiện tại và phiên bản đích để xem diff của các file template native, rồi áp từng thay đổi vào dự án; đọc kèm changelog và bài blog release về breaking change.</li><li><b>Expo</b>: <code>npx expo install expo@^&lt;SDK&gt;</code> rồi <code>npx expo install --fix</code> để đưa thư viện về phiên bản tương thích, <code>npx expo-doctor</code> để kiểm tra; dùng CNG thì chỉ cần <code>prebuild --clean</code>. Expo khuyến nghị nâng từng SDK một.</li><li><b>Kiểm thư viện</b>: liệt kê dependency native, tra React Native Directory về hỗ trợ New Architecture và phiên bản; thư viện bỏ hoang thì thay, fork, hoặc vá bằng <code>patch-package</code>.</li><li><b>Nâng từng bước</b>: cách xa nhiều bản thì đi qua từng mốc (ví dụ bật New Architecture ở bản còn cho tắt rồi mới lên 0.82 trở đi); mỗi bước là một PR, build chạy được và test xong mới đi tiếp.</li></ul> Sau cùng chạy đủ test và E2E, test tay trên hai nền tảng kể cả máy cũ (<code>minSdk</code> và iOS tối thiểu có thể đã tăng), rồi phát hành theo staged rollout. Với OTA: runtime version phải đổi vì phần native đã thay đổi.", x:"Kể theo STAR: Expense Tracker đang ở Expo SDK 50, phải nâng vì Google Play yêu cầu target SDK mới. Cách làm: nâng lần lượt từng SDK, mỗi bước chạy <code>expo install --fix</code> và <code>expo-doctor</code>; tại SDK 53 bật New Architecture thì thư viện biểu đồ cũ hỏng, nên thay bằng thư viện dựng trên Skia; một thư viện nhỏ lỗi build Gradle thì vá tạm bằng patch-package và mở PR cho upstream. Khi đã ổn trên New Architecture mới nâng tiếp lên các SDK chỉ còn New Architecture. Kết quả: xong trong hai tuần, rollout 10% rồi 100% mà crash không tăng.<pre>npx expo install expo@^53.0.0\nnpx expo install --fix\nnpx expo-doctor\nnpx expo prebuild --clean                     # nếu dùng CNG\nnpx patch-package react-native-legacy-chart   # sau khi sửa trong node_modules</pre>"},
  "w6k0": {c:"Đây là bộ công cụ đo hiệu năng app RN: React DevTools Profiler đo component nào render và mất bao lâu; React Native DevTools là debugger chính thức (console, breakpoint, memory, profiler); Perf Monitor hiện FPS của JS thread và UI thread ngay trên máy; Hermes profile ghi lại CPU của JS engine để tìm hàm tốn thời gian.", e:"<ul><li><b>React Profiler</b> (nằm trong React Native DevTools): ghi lại một thao tác rồi xem flamegraph của từng commit, thời gian render từng component và lý do render (bật “Record why each component rendered”); tuỳ chọn highlight updates để thấy vùng nào render lại.</li><li><b>React Native DevTools</b>: mở từ dev menu hoặc phím <code>j</code> trong terminal Metro; dựa trên Chrome DevTools, debug trực tiếp Hermes, thay cho Flipper và debugger Chrome cũ. Từ RN 0.83 có thêm panel Network và Performance; panel Memory chụp heap snapshot.</li><li><b>Perf Monitor</b> (trong dev menu): JS FPS tụt nghĩa là JS thread bận; UI FPS tụt nghĩa là main thread bận (quá nhiều view, decode ảnh, code native nặng).</li><li><b>Hermes profile</b>: ghi CPU sampling của JS (panel Performance hoặc profiler của Hermes) để tìm hàm tốn CPU như parse, sort, format lặp đi lặp lại.</li></ul> Nguyên tắc: đo trên <b>release build</b> (hoặc profiling build) và máy Android tầm trung, vì dev mode chậm hơn nhiều và làm sai lệch kết quả; ghi lại số đo trước và sau để chứng minh hiệu quả.", x:"Màn Reports mở mất 1,8 giây trên một máy Android tầm trung. Quy trình đo: Perf Monitor cho thấy JS FPS rơi về gần 0 khi mở màn còn UI FPS vẫn 60, nghĩa là vấn đề nằm ở JS. Panel Performance chỉ ra 900 ms nằm trong <code>groupByCategory</code>, hàm này tạo object ngày cho từng giao dịch. React Profiler cho thấy <code>ReportsScreen</code> commit 3 lần liền do ba state được set riêng sau ba request. Sửa: tổng hợp bằng SQL, gộp state, đo lại còn 450 ms, ghi số liệu vào PR. Có thể đo khoanh vùng ngay trong code (component <code>Profiler</code> chỉ hoạt động ở dev và profiling build):<pre>const t0 = performance.now();\nconst groups = groupByCategory(txs);\nconsole.log(`groupByCategory: ${(performance.now() - t0).toFixed(1)} ms`);\n\n&lt;Profiler id='Reports' onRender={(id, phase, actualDuration) =&gt; {\n  if (actualDuration &gt; 16) console.warn(id, phase, `${actualDuration.toFixed(1)} ms`);\n}}&gt;\n  &lt;ReportsScreen /&gt;\n&lt;/Profiler&gt;</pre>"},
  "w6k1": {c:"Tối ưu re-render là giảm số lần React phải gọi lại component một cách không cần thiết, bằng cách giữ props ổn định, chia nhỏ component để state chỉ ảnh hưởng một vùng nhỏ, và chỉ subscribe đúng phần store cần dùng.", e:"<ul><li><b>memo</b>: <code>React.memo</code> cho item của list và component nặng; chỉ có tác dụng khi props giữ nguyên tham chiếu.</li><li><b>Tách component</b>: đẩy state xuống gần nơi dùng (ô tìm kiếm giữ state riêng thay vì đặt ở màn cha), hoặc truyền phần tĩnh qua <code>children</code> để phần đó không bị render theo.</li><li><b>Selector</b>: <code>useSelector(s =&gt; s.txs.byId[id])</code> hay <code>useStore(s =&gt; s.month)</code> chỉ render khi phần được chọn thay đổi. Selector trả về object hoặc mảng mới mỗi lần (<code>filter</code>, <code>map</code>, <code>{a, b}</code>) thì component luôn render, phải dùng <code>createSelector</code> hoặc <code>useShallow</code>.</li><li><b>Tránh inline object/func ở list item</b>: <code>style={{...}}</code>, <code>onPress={() =&gt; ...}</code>, <code>item={{...item, x}}</code> tạo tham chiếu mới mỗi lần nên phá <code>memo</code>. Hãy truyền id cùng một handler ổn định (<code>useCallback</code>), đưa style tĩnh vào <code>StyleSheet</code>; <code>renderItem</code> và <code>keyExtractor</code> của FlatList cũng nên ổn định, <code>extraData</code> chỉ dùng khi thật cần.</li></ul> React Compiler tự lo phần lớn việc memo hoá, nhưng không sửa được selector trả về object mới hay state đặt sai chỗ.", x:"Danh sách giao dịch giật mỗi khi có giao dịch mới đến qua WebSocket: Profiler cho thấy cả 50 dòng đang hiển thị đều render lại với mỗi message. Nguyên nhân: row nhận <code>style</code> và <code>onPress</code> inline, và selector trả về mảng mới. Sửa:<pre>// Trước: mảng mới mỗi lần store đổi, props inline\nconst txs = useStore(s =&gt; s.txs.filter(t =&gt; t.month === month));\nrenderItem={({ item }) =&gt; &lt;TxRow tx={item} style={{ padding: 12 }} onPress={() =&gt; open(item.id)} /&gt;}\n\n// Sau\nconst ids = useStore(s =&gt; s.idsByMonth[month] ?? EMPTY); // tham chiếu ổn định\nconst onOpen = useCallback((id: string) =&gt; open(id), [open]);\nconst renderItem = useCallback(({ item }: { item: string }) =&gt;\n  &lt;TxRow id={item} onPress={onOpen} /&gt;, [onOpen]);\n\nconst TxRow = memo(function TxRow({ id, onPress }: RowProps) {\n  const tx = useStore(s =&gt; s.txById[id]); // mỗi dòng chỉ theo dõi item của nó\n  return &lt;Pressable style={styles.row} onPress={() =&gt; onPress(id)}&gt;&lt;Text&gt;{tx.note}&lt;/Text&gt;&lt;/Pressable&gt;;\n});</pre>"},
  "w6k2": {c:"Startup time là khoảng thời gian từ lúc người dùng chạm vào icon tới khi màn đầu tiên dùng được (TTI). Với RN, nó gồm khởi tạo native, nạp và chạy JS bundle, render màn đầu, và tải dữ liệu đầu tiên.", e:"<ul><li><b>Hermes bytecode</b>: bản release biên dịch JS thành bytecode lúc build; engine nạp bytecode vào bộ nhớ khi cần mà không phải parse như JS thuần, nên bundle lớn ít ảnh hưởng tới startup hơn.</li><li><b>Lazy require và inline requires</b>: module chỉ được thực thi khi dùng tới lần đầu, thay vì chạy mọi <code>import</code> ở root khi mở app. Với React Native CLI, <code>require</code> được inline tự động; với Expo, tài liệu RN hướng dẫn bật <code>inlineRequires</code> trong Metro config. Màn hình nặng nên lazy load (<code>React.lazy</code> hoặc <code>getComponent</code> của React Navigation); cẩn thận với module có side effect vì thứ tự thực thi thay đổi.</li><li><b>Giảm bundle</b>: bỏ thư viện nặng không cần thiết (moment thay bằng dayjs hoặc <code>Intl</code>, import lodash theo từng hàm), tránh barrel file kéo cả thư mục, phân tích bằng <code>source-map-explorer</code> hoặc Expo Atlas.</li><li><b>Khác</b>: trì hoãn SDK chưa cần ngay (analytics, chat), hiện dữ liệu cache thay vì chờ mạng mới vẽ màn đầu, giữ splash tới khi màn đầu sẵn sàng thay vì hiện màn trắng, giảm việc nặng ở <code>Application.onCreate</code> và <code>AppDelegate</code>.</li></ul> Đo bằng mốc thời gian trong log, Android Studio/Perfetto, Instruments (App Launch), trên release build, máy yếu, và cold start.", x:"Cold start mất 4,2 giây trên máy Android tầm trung. Đo thấy 1,3 giây là JS thực thi module ở root: <code>App.tsx</code> import cả 30 màn hình, thư viện biểu đồ, thư viện xuất PDF, và khởi tạo đồng bộ Analytics, Sentry, Remote Config. Sau khi lazy load các màn ít dùng, bật inline requires, trì hoãn analytics tới sau màn đầu và hiện số dư từ cache MMKV, cold start còn 2,1 giây.<pre>// metro.config.js (Expo)\nconst { getDefaultConfig } = require('expo/metro-config');\nconst config = getDefaultConfig(__dirname);\nconfig.transformer.getTransformOptions = async () =&gt; ({\n  transform: { experimentalImportSupport: false, inlineRequires: true },\n});\nmodule.exports = config;\n\n// Màn ít dùng: chỉ require khi người dùng mở tới\n&lt;Stack.Screen name='ExportPdf' getComponent={() =&gt; require('./ExportPdfScreen').default} /&gt;</pre>"},
  "w6k3": {c:"Memory leak là tình trạng bộ nhớ không được giải phóng vì vẫn còn tham chiếu tới object không còn dùng, thường do listener, timer hoặc subscription vẫn sống sau khi component đã unmount.", e:"<ul><li><b>Listener chưa remove</b>: <code>AppState</code>, <code>Keyboard</code>, <code>Dimensions</code>, <code>NetInfo</code>, <code>Linking</code>, <code>DeviceEventEmitter</code>, listener của navigation. Các API này trả về subscription hoặc hàm huỷ, phải gọi trong cleanup của <code>useEffect</code>.</li><li><b>Timer</b>: <code>setInterval</code>/<code>setTimeout</code> không được clear, nhất là interval polling vẫn chạy khi màn đã đóng, giữ closure tham chiếu tới state lớn.</li><li><b>Subscription</b>: WebSocket, <code>onSnapshot</code> của Firestore, observable của WatermelonDB, event của native module; quên huỷ vừa leak bộ nhớ vừa tốn pin và dữ liệu mạng.</li><li><b>Nguồn khác</b>: cache ở module scope phình mãi (Map không giới hạn), ảnh lớn không resize, giữ ref tới component hoặc view trong biến global.</li></ul> Cách phát hiện: panel Memory của React Native DevTools (chụp heap snapshot, so sánh hai snapshot sau khi mở và đóng một màn nhiều lần), Android Studio Memory Profiler, Xcode Instruments (Allocations, Leaks). Dấu hiệu điển hình: bộ nhớ tăng theo bậc thang mỗi lần vào ra một màn và không giảm sau GC. Cảnh báo “setState on unmounted component” đã bị bỏ từ React 18 vì hay báo sai, nên đừng dựa vào nó.", x:"Người dùng báo app chậm dần rồi bị hệ điều hành kill sau khoảng 30 phút. Heap snapshot sau 10 lần mở và đóng màn chi tiết ví cho thấy vẫn còn 10 bản <code>WalletDetail</code>: mỗi lần mở đều đăng ký socket và interval polling nhưng không huỷ. Bản sửa dọn đủ mọi thứ trong cleanup:<pre>useEffect(() =&gt; {\n  const unsubscribeSocket = socket.subscribe(`wallet:${id}`, onBalance);\n  const poll = setInterval(refetch, 15000);\n  const appSub = AppState.addEventListener('change', s =&gt; { if (s === 'active') refetch(); });\n  const kbSub = Keyboard.addListener('keyboardDidShow', onKeyboard);\n  return () =&gt; {\n    unsubscribeSocket();\n    clearInterval(poll);\n    appSub.remove();\n    kbSub.remove();\n  };\n}, [id, refetch]);</pre> Sau khi sửa, lặp lại thao tác và chụp snapshot lần nữa để xác nhận số instance không còn tăng."},
  "w6k4": {c:"Animation đạt 60fps (hoặc 120fps trên màn hình tần số cao) khi mỗi khung hình được tính xong trong khoảng 16,7 ms (hoặc 8,3 ms). Trong RN, cách chắc chắn nhất là để animation chạy trên UI thread, không phụ thuộc JS thread đang bận hay rảnh.", e:"Nếu animation được điều khiển từ JS (setState mỗi khung hình, hoặc Animated không bật native driver), mỗi frame phải đi qua JS thread rồi mới tới UI; JS đang render list hay parse JSON là animation khựng. <b>Animated với <code>useNativeDriver: true</code></b>: gửi toàn bộ mô tả animation sang native một lần và native tự chạy, nhưng chỉ hỗ trợ thuộc tính không ảnh hưởng layout, chủ yếu <code>transform</code> và <code>opacity</code>; không dùng được với <code>width</code>, <code>height</code>, <code>top</code>. <b>Reanimated</b>: logic animation là worklet chạy trên UI thread, đọc trực tiếp dữ liệu gesture, animate được cả thuộc tính layout, có <code>withTiming</code>, <code>withSpring</code>, <code>withDecay</code>, layout animation (<code>entering</code>, <code>exiting</code>), và từ v4 có thêm CSS animation và transition. Mẹo khác: ưu tiên <code>transform</code> thay vì đổi layout (để Yoga không phải tính lại mỗi frame), giảm số view đang animate, tránh shadow hay blur lớn trên Android, không cập nhật React state theo từng frame, và đo trên release build bằng Perf Monitor.", x:"Bottom sheet chọn danh mục được viết bằng <code>Animated</code> và animate <code>height</code> (không bật được native driver), nên khựng mỗi khi mở đúng lúc màn đang tải dữ liệu. Viết lại bằng Reanimated với <code>translateY</code>:<pre>const SHEET_H = 420;\nconst y = useSharedValue(SHEET_H);\nuseEffect(() =&gt; {\n  y.value = withSpring(open ? 0 : SHEET_H, { damping: 20, stiffness: 180 });\n}, [open]);\nconst sheetStyle = useAnimatedStyle(() =&gt; ({ transform: [{ translateY: y.value }] }));\nconst backdropStyle = useAnimatedStyle(() =&gt; ({\n  opacity: interpolate(y.value, [0, SHEET_H], [0.5, 0]),\n}));\n\n// Với Animated cũ: chỉ transform/opacity mới bật được native driver\nAnimated.timing(fade, { toValue: 1, duration: 200, useNativeDriver: true }).start();</pre>"},
  "w6k5": {c:"Jest là test runner chạy test JavaScript trong Node; React Native Testing Library (RNTL) render component trong môi trường test và cung cấp API để truy vấn, tương tác theo cách người dùng nhìn thấy (chữ, role, label) thay vì theo chi tiết cài đặt.", e:"Nguyên tắc: test hành vi, không test implementation. Truy vấn ưu tiên <code>getByRole('button', { name: 'Lưu' })</code>, <code>getByLabelText</code>, <code>getByText</code>, <code>getByPlaceholderText</code>; <code>testID</code> là phương án cuối cùng. <code>getBy*</code> ném lỗi nếu không tìm thấy, <code>queryBy*</code> trả về null để kiểm tra phần tử vắng mặt, <code>findBy*</code> chờ kết quả bất đồng bộ. Tương tác bằng <code>userEvent</code> (<code>setup()</code>, <code>press</code>, <code>type</code>) mô phỏng chuỗi sự kiện thật, hoặc <code>fireEvent</code> cho trường hợp đơn giản. Có sẵn matcher như <code>toBeOnTheScreen</code>, <code>toBeDisabled</code>, <code>toHaveTextContent</code>. <b>Mock module native</b>: Jest chạy trong Node, không có native, nên phải mock (<code>jest.mock('expo-secure-store')</code>, thư mục <code>__mocks__</code>, hoặc mock có sẵn của thư viện như Reanimated, AsyncStorage, NetInfo); API thì mock ở tầng network bằng MSW hoặc mock module <code>api</code>. Preset <code>jest-expo</code> hoặc <code>react-native</code> đã cấu hình sẵn transform. Tránh snapshot lớn vì vỡ liên tục mà không ai đọc; tránh kiểm tra state nội bộ hay số lần gọi hàm private.", x:"Test form thêm giao dịch: báo lỗi khi bỏ trống số tiền, gọi API khi hợp lệ, và hiện thông báo thành công. Test không quan tâm form dùng useState hay reducer:<pre>import * as api from '@/api';\njest.mock('@/api', () =&gt; ({ addTx: jest.fn().mockResolvedValue({ id: '1' }) }));\n\ntest('báo lỗi khi số tiền trống, lưu khi hợp lệ', async () =&gt; {\n  const user = userEvent.setup();\n  render(&lt;AddTxForm /&gt;, { wrapper: QueryProvider });\n\n  await user.press(screen.getByRole('button', { name: 'Lưu' }));\n  expect(screen.getByText('Vui lòng nhập số tiền')).toBeOnTheScreen();\n\n  await user.type(screen.getByLabelText('Số tiền'), '150000');\n  await user.press(screen.getByRole('button', { name: 'Lưu' }));\n  expect(await screen.findByText('Đã lưu giao dịch')).toBeOnTheScreen();\n  expect(api.addTx).toHaveBeenCalledWith(expect.objectContaining({ amount: 150000 }));\n});</pre>"},
  "w6k6": {c:"E2E (end-to-end) test chạy bản build thật của app trên simulator, emulator hoặc thiết bị và điều khiển app như người dùng để kiểm tra trọn một luồng; Detox và Maestro là hai công cụ phổ biến cho React Native.", e:"<ul><li><b>Detox</b> (của Wix): test viết bằng JS/TS chạy cùng Jest, kiểu gray-box: tự đồng bộ với trạng thái app (chờ network, animation, timer xong) nên ít phải <code>sleep</code>. Đổi lại cần cấu hình build riêng cho từng nền tảng, setup khá nặng và nhạy với phiên bản RN.</li><li><b>Maestro</b>: flow viết bằng YAML, kiểu black-box, chạy trên app đã build mà không phải sửa code app; tự chờ và retry, có Maestro Studio để ghi thao tác; dễ bắt đầu và chạy được trên CI. Nhược điểm là logic phức tạp (rẽ nhánh, dữ liệu động) kém linh hoạt hơn code.</li></ul> Cả hai nên tìm phần tử qua <code>testID</code> hoặc accessibility label ổn định. Chỉ giữ vài luồng quan trọng nhất (đăng nhập, thêm giao dịch, thanh toán), vì E2E chậm và dễ flaky. Nguyên nhân flaky hay gặp: dữ liệu backend không cố định, animation, popup xin quyền của hệ thống, mạng thật. Giảm bằng backend staging có seed dữ liệu hoặc mock server, tắt animation, cấp quyền trước, chạy trên emulator cố định trong CI.", x:"Luồng chính của Expense Tracker viết bằng Maestro (file <code>.maestro/add-transaction.yaml</code>), chạy mỗi đêm trên bản build staging; ô số tiền tự focus khi mở form:<pre>appId: com.expense.tracker\n---\n- launchApp:\n    clearState: true\n- tapOn: 'Email'\n- inputText: 'qa@example.com'\n- tapOn: 'Mật khẩu'\n- inputText: 'Test1234!'\n- tapOn: 'Đăng nhập'\n- assertVisible: 'Tổng quan'\n- tapOn:\n    id: 'add-tx-button'\n- inputText: '150000'\n- tapOn: 'Lưu'\n- assertVisible: 'Đã lưu giao dịch'</pre>"},
  "w6k7": {c:"Sentry là dịch vụ theo dõi lỗi và hiệu năng; với RN, SDK <code>@sentry/react-native</code> bắt lỗi JS, crash native, ANR, ghi lại ngữ cảnh trước khi lỗi xảy ra, và tổng hợp sức khoẻ của từng phiên bản phát hành.", e:"<ul><li><b>Source map</b>: JS ở bản release đã được minify (và biên dịch thành bytecode Hermes), nên stack trace chỉ trỏ vào kiểu <code>index.android.bundle:1:48213</code>. Phải upload source map đúng với từng bundle (gắn <code>release</code> và <code>dist</code>) để Sentry đổi về file và dòng gốc; phần native cần dSYM (iOS) và mapping R8 (Android). Plugin Expo, Gradle plugin, build phase Xcode của Sentry làm việc này tự động; với OTA update thì phải upload source map cho từng update.</li><li><b>Breadcrumb</b>: chuỗi sự kiện trước lỗi (chuyển màn hình, request HTTP, console, tap) được ghi tự động; có thể thêm breadcrumb cho các hành động nghiệp vụ; lọc dữ liệu nhạy cảm trong <code>beforeBreadcrumb</code> và <code>beforeSend</code>.</li><li><b>Release health</b>: theo dõi session, tỉ lệ crash-free sessions và crash-free users theo từng release, mức độ người dùng đã lên bản mới; dùng để quyết định tăng hay dừng staged rollout.</li></ul> Thêm: bọc root bằng <code>Sentry.wrap(App)</code>, gắn user id (không gửi email nếu không cần), tách environment, đặt <code>tracesSampleRate</code> thấp ở production để kiểm soát chi phí, và tạo alert khi release có issue mới.", x:"Sau bản 2.3.0, Sentry báo <code>TypeError: undefined is not an object (evaluating 't.amount.toFixed')</code> nhưng stack chỉ trỏ vào <code>main.jsbundle</code>. Nguyên nhân: CI build bằng lệnh thủ công nên không upload source map. Sửa pipeline rồi đọc lại: lỗi ở <code>formatAmount</code> khi API trả <code>amount: null</code> cho giao dịch nháp; breadcrumb cho thấy người dùng vừa mở màn Nháp. Cấu hình (plugin <code>@sentry/react-native/expo</code> trong app.json lo upload source map khi build):<pre>Sentry.init({\n  dsn: process.env.EXPO_PUBLIC_SENTRY_DSN,   // DSN không phải secret\n  environment: __DEV__ ? 'development' : 'production',\n  tracesSampleRate: 0.1,\n  beforeSend(event) {\n    if (event.user) delete event.user.email;  // không gửi PII\n    return event;\n  },\n});\nSentry.addBreadcrumb({ category: 'tx', message: 'Open drafts', level: 'info' });\nexport default Sentry.wrap(App);</pre>"},
  "w6k8": {c:"Profiling native là đo CPU, bộ nhớ và năng lượng ở tầng hệ điều hành bằng công cụ của Apple và Google. Nó cần thiết khi vấn đề nằm ngoài JS: main thread bị chặn, cây view quá nặng, native module chậm, rò rỉ bộ nhớ native.", e:"<ul><li><b>Xcode Instruments, Time Profiler</b>: lấy mẫu stack của mọi thread theo thời gian; lọc theo main thread, bật “Hide System Libraries” và “Invert Call Tree” để thấy hàm tốn CPU nhất. Phần JS chạy trong Hermes chỉ hiện thành các hàm C++ của engine, nên phải kết hợp thêm Hermes profile.</li><li><b>Allocations và Leaks</b>: theo dõi bộ nhớ theo thời gian; dùng Mark Generation trước và sau khi mở rồi đóng một màn để thấy cái gì không được giải phóng; Leaks phát hiện retain cycle.</li><li><b>Android Studio Profiler</b>: CPU (System Trace hoặc callstack sampling, xem main thread, RenderThread và thread JS), Memory (heap dump, theo dõi bộ nhớ Java/Kotlin và native, phát hiện Activity bị leak). Perfetto cho trace hệ thống chi tiết hơn, thấy rõ frame bị trễ.</li></ul> Profile trên bản release hoặc bản cho phép profile (<code>profileable</code> trên Android, scheme Profile trên iOS) và thiết bị thật, vì simulator và debug build không phản ánh đúng. Kết hợp với Perf Monitor: UI FPS tụt thì mở công cụ native, JS FPS tụt thì xem Hermes profile trước.", x:"Cuộn danh sách hoá đơn trên iPhone 11 bị giật dù JS FPS vẫn 60, UI FPS tụt còn 35. Time Profiler trên main thread cho thấy phần lớn thời gian nằm ở <code>ImageIO</code> decode JPEG cỡ lớn và vẽ bóng của từng ô. Sửa: dùng thumbnail đúng kích thước, bỏ bóng trong item list (hoặc đảm bảo view có <code>backgroundColor</code> để iOS không phải tính bóng theo nội dung). Trên Android, Memory Profiler cho thấy bộ nhớ native tăng 80 MB sau khi mở 20 ảnh vì bitmap full-size. Để profile được bản release trên Android:<pre>&lt;!-- AndroidManifest.xml: cho phép profile bản release --&gt;\n&lt;application&gt;\n  &lt;profileable android:shell=\"true\" /&gt;\n&lt;/application&gt;\n\n# Ghi trace hệ thống 10 giây rồi mở bằng ui.perfetto.dev\nadb shell perfetto -o /data/misc/perfetto-traces/trace.perfetto-trace -t 10s sched freq gfx view am\nadb pull /data/misc/perfetto-traces/trace.perfetto-trace</pre>"},
  "w6k9": {c:"Triage crash production là quy trình phân loại và xử lý crash của người dùng thật: đọc stack trace đã symbolicate, nhóm theo phiên bản và thiết bị để đánh giá mức ảnh hưởng, tái hiện lỗi, rồi quyết định mức ưu tiên và cách sửa.", e:"<ul><li><b>Đọc stack trace đã symbolicate</b>: cần source map (JS), dSYM (iOS), mapping R8 và symbol NDK (Android) đúng với từng build. Tìm frame đầu tiên thuộc code của mình, đọc message, phân biệt crash JS, crash native, ANR và OOM (thường không có stack, chỉ thấy app bị kill).</li><li><b>Nhóm theo release và thiết bị</b>: issue mới xuất hiện từ release nào, chỉ trên Android 10, chỉ một hãng máy, chỉ khi bộ nhớ thấp, hay chỉ ở người dùng nâng cấp từ bản cũ (lỗi migrate dữ liệu). Đây là manh mối để khoanh vùng.</li><li><b>Tái hiện</b>: dựng lại theo breadcrumb, đúng phiên bản OS và loại thiết bị (Firebase Test Lab, BrowserStack), với dữ liệu tương tự; viết test tái hiện trước khi sửa.</li><li><b>Ưu tiên</b>: theo số người dùng bị ảnh hưởng, tần suất, mức nghiêm trọng (crash lúc mở app hay ở màn ít dùng), luồng có liên quan tiền hoặc dữ liệu không; crash-free rate xuống dưới ngưỡng thì dừng rollout ngay.</li></ul> Cách sửa: lỗi JS có thể hotfix qua OTA, lỗi native cần build mới; trong lúc chờ có thể tắt tính năng bằng Remote Config (kill switch). Sau đó viết postmortem và thêm alert.", x:"Sáng thứ hai, crash-free users của bản 3.1.0 giảm từ 99,7% xuống 98,2% khi đang rollout 20%. Sentry có issue mới <code>IllegalStateException</code> trong thư viện chọn giờ, 92% xảy ra trên Android 14 máy Xiaomi khi máy để định dạng 12 giờ. Quyết định: dừng rollout trên Play Console; tắt màn chọn giờ mới bằng Remote Config để quay về picker cũ; tái hiện trên emulator Android 14 với định dạng 12 giờ; sửa rồi phát hành 3.1.1, rollout lại từ 10%. Báo cáo ngắn gửi team (cũng là khung để kể khi phỏng vấn):<pre>Lỗi:       IllegalStateException trong TimePickerDialog (v3.1.0, build 310)\nẢnh hưởng: 1.320 user / 24h, 1,5% session, Android 14, 92% Xiaomi\nTừ khi:    3.1.0 (tính năng mới: giờ nhắc nhở)\nTái hiện:  Android 14 + đồng hồ 12h, mở Nhắc nhở rồi đổi giờ\nXử lý:     dừng rollout 20%; Remote Config new_time_picker = false\nSửa:       3.1.1 build 311, rollout 10% → 50% → 100%\nPhòng ngừa: thêm test case, alert khi issue mới vượt 0,5% user</pre>"},
  "w7k0": {c:"Versioning là cách đánh số phiên bản app: số hiển thị cho người dùng (<code>versionName</code>, <code>CFBundleShortVersionString</code>) theo semver, và số build tăng dần mỗi lần upload (<code>versionCode</code>, <code>CFBundleVersion</code>). Môi trường dev, staging, prod là các biến thể build trỏ tới backend và cấu hình khác nhau.", e:"<ul><li><b>versionCode</b> (Android): số nguyên, bản upload sau lên Play phải lớn hơn bản trước, tối đa 2.100.000.000. <b>CFBundleVersion</b> (iOS): số build, phải tăng trong cùng một phiên bản marketing. Người dùng thấy <code>1.4.0</code>, còn store xét số build. Với Expo, đặt <code>version</code> trong app.json và để EAS quản lý số build (<code>appVersionSource: remote</code>, <code>autoIncrement: true</code>) để không bị trùng khi nhiều người cùng build.</li><li><b>Semver</b> <code>MAJOR.MINOR.PATCH</code>: với app, thường tăng MAJOR khi thay đổi lớn hoặc bắt buộc cập nhật, MINOR cho tính năng mới, PATCH cho hotfix; OTA update không làm đổi version của binary.</li><li><b>Môi trường</b>: mỗi môi trường có API URL, Sentry environment, Firebase project riêng, có thể có bundle ID/applicationId riêng (<code>com.expense.tracker.staging</code>) để cài song song trên cùng một máy, kèm tên và icon khác để QA không nhầm. Làm bằng product flavor (Android) và scheme/configuration (iOS), hoặc với Expo là <code>app.config.ts</code> đọc biến môi trường cùng các profile trong <code>eas.json</code>.</li></ul> Không đưa secret vào biến <code>EXPO_PUBLIC_*</code>, chỉ để cấu hình công khai.", x:"QA tưởng bản staging là bản production và báo lỗi số dư sai, vì hai bản cùng icon, cùng bundle ID. Tách biến thể theo môi trường:<pre>// app.config.ts\nconst env = process.env.APP_ENV ?? 'development';\nconst suffix = env === 'production' ? '' : `.${env}`;\nexport default {\n  name: env === 'production' ? 'Expense Tracker' : `Expense (${env})`,\n  version: '1.4.0',                                   // semver người dùng thấy\n  ios: { bundleIdentifier: `com.expense.tracker${suffix}` },\n  android: { package: `com.expense.tracker${suffix}` },\n  extra: { apiUrl: env === 'production' ? 'https://api.expense.app' : 'https://staging-api.expense.app' },\n};\n// eas.json: \"cli\": { \"appVersionSource\": \"remote\" },\n//   \"build\": { \"production\": { \"env\": { \"APP_ENV\": \"production\" }, \"autoIncrement\": true } }</pre>"},
  "w7k1": {c:"Signing là việc ký số file build bằng khoá riêng để hệ điều hành và store xác minh app đến từ đúng nhà phát triển và không bị sửa đổi. Android dùng keystore; iOS dùng certificate kết hợp với provisioning profile.", e:"<ul><li><b>Android</b>: keystore (<code>.jks</code> hoặc <code>.keystore</code>) chứa private key, có alias và mật khẩu. Với Play App Signing (bắt buộc với app mới phát hành bằng AAB), bạn ký AAB bằng <b>upload key</b>, còn Google giữ <b>app signing key</b> và dùng nó ký bản giao tới người dùng. Mất upload key thì có thể yêu cầu reset; còn thời tự ký trước đây, mất key là không bao giờ cập nhật được app nữa. SHA-1/SHA-256 của app signing key (xem trên Play Console) là thứ cần khai cho Google Sign-In, Firebase, App Links.</li><li><b>iOS</b>: <b>certificate</b> (Development hoặc Distribution) xác nhận danh tính người ký, private key nằm trong Keychain của máy đã tạo nó; <b>App ID</b> gồm bundle ID và các capability (Push, Associated Domains...); <b>provisioning profile</b> gắn certificate, App ID, entitlements (và danh sách thiết bị với bản development/ad hoc) lại với nhau. Lỗi hay gặp: profile chưa có capability vừa bật, certificate hết hạn, máy CI thiếu private key.</li></ul> Quản lý: không commit keystore hay certificate; lưu trong secret của CI hoặc để EAS credentials hay Fastlane match quản lý, có người chịu trách nhiệm và bản backup an toàn.", x:"CI build iOS lỗi “No profile for team matching 'com.expense.tracker' found” ngay sau khi thêm Sign in with Apple, vì profile cũ chưa có capability mới. Tạo lại profile (hoặc để EAS hay match tự sinh) rồi build lại. Với Android, tạo upload key và cấu hình ký AAB:<pre># Tạo upload key (giữ file và mật khẩu trong secret manager, không commit)\nkeytool -genkeypair -v -storetype PKCS12 -keystore upload.keystore \\\n  -alias upload -keyalg RSA -keysize 2048 -validity 10000\n\n# android/app/build.gradle\nsigningConfigs {\n  release {\n    storeFile file(System.getenv('UPLOAD_STORE_FILE'))\n    storePassword System.getenv('UPLOAD_STORE_PASSWORD')\n    keyAlias 'upload'\n    keyPassword System.getenv('UPLOAD_KEY_PASSWORD')\n  }\n}\n# SHA-256 để khai Firebase/App Links: lấy của app signing key trên Play Console</pre>"},
  "w7k2": {c:"EAS (Expo Application Services) là dịch vụ cloud của Expo gồm EAS Build (build app trên server), EAS Submit (đẩy bản build lên store) và EAS Update (phát hành OTA). Fastlane là bộ công cụ mã nguồn mở tự động hoá build, ký và phát hành trên máy của bạn. GitHub Actions là nền tảng CI/CD chạy workflow theo sự kiện của repo.", e:"<ul><li><b>EAS Build</b>: profile cấu hình trong <code>eas.json</code> (development, preview, production), tự quản lý credentials (keystore, certificate, profile), build được iOS mà không cần máy Mac; có cache và hàng đợi, tính phí theo gói; <code>--local</code> để build trên máy mình.</li><li><b>EAS Submit</b>: <code>eas submit</code> hoặc cờ <code>--auto-submit</code> đẩy AAB lên track của Play và IPA lên TestFlight, dùng service account (Google) và App Store Connect API key (Apple).</li><li><b>EAS Update</b>: phát JS và asset theo channel (preview, production) gắn với từng build.</li><li><b>Fastlane</b>: các action như <code>match</code> (đồng bộ certificate và profile qua repo mã hoá), <code>build_app</code>, <code>pilot</code> (TestFlight), <code>supply</code> (Play), <code>increment_build_number</code>; hợp với dự án bare hoặc khi muốn tự kiểm soát hạ tầng, nhưng cần máy macOS cho iOS và tự bảo trì.</li><li><b>GitHub Actions</b>: workflow bằng YAML; mỗi PR chạy lint, typecheck, test; merge vào main thì kích hoạt build; secrets lưu theo repo hoặc environment; runner macOS đắt hơn runner Linux nhiều lần.</li></ul> Cách kết hợp hay gặp: GitHub Actions điều phối, gọi EAS để build và submit (hoặc chạy Fastlane trên runner macOS).", x:"Pipeline cho Expense Tracker: mỗi PR chạy kiểm tra; push vào <code>main</code> thì build bản preview cho QA và đẩy OTA lên channel staging:<pre>on: { pull_request: {}, push: { branches: [main] } }\njobs:\n  ci:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with: { node-version: 22, cache: npm }\n      - run: npm ci &amp;&amp; npx tsc --noEmit &amp;&amp; npx eslint . &amp;&amp; npx jest --ci\n      - uses: expo/expo-github-action@v8\n        with: { eas-version: latest, token: '${{ secrets.EXPO_TOKEN }}' }\n      - if: github.event_name == 'push'\n        run: |\n          eas build --platform all --profile preview --non-interactive --no-wait\n          eas update --channel staging --message 'CI build' --non-interactive</pre>"},
  "w7k3": {c:"OTA (over-the-air) update là cơ chế tải JS bundle và asset mới từ server về app đã cài, không phải phát hành bản mới qua store; với Expo, đó là EAS Update.", e:"Khi khởi động, app kiểm tra update theo channel của build; mặc định bản mới được tải ngầm và áp dụng ở lần mở sau (có thể cấu hình kiểm tra ngay, hoặc chủ động gọi <code>checkForUpdateAsync</code>, <code>fetchUpdateAsync</code>, <code>reloadAsync</code>). <b>Runtime version</b> là “hợp đồng” giữa JS và native: update chỉ được giao tới build có cùng runtime version, nên mọi thay đổi native (thêm thư viện native, nâng RN hay SDK, đổi permission, config plugin) đều phải tăng runtime version và phát hành build mới. Policy <code>appVersion</code> gắn runtime theo version của app; policy <code>fingerprint</code> tự tính hash từ phần native nên tránh được lỗi quên tăng. <b>Giới hạn</b>: không đổi được native code, không thêm được quyền, và phải theo chính sách store (Apple chỉ chấp nhận OTA không làm thay đổi mục đích chính của app). Rủi ro: update lỗi đến tay mọi người dùng gần như ngay lập tức, nên cần rollout theo %, có sẵn rollback, và upload source map cho từng update. <b>CodePush</b> ngừng cùng Microsoft App Center từ 31/03/2025; dự án cũ phải chuyển sang EAS Update hoặc tự host server CodePush mã nguồn mở.", x:"Thứ sáu phát hiện màn báo cáo tính sai tổng chi do lỗi làm tròn trong JS. Vì chỉ sửa JS nên phát hành qua EAS Update cho đúng runtime version của bản đang chạy, rollout 10% trước rồi tăng dần. Tuần sau thêm thư viện quét mã QR (native) thì bắt buộc build mới; runtime version đổi theo nên update cũ không bị đẩy nhầm sang build mới.<pre>// app.json\n\"runtimeVersion\": { \"policy\": \"fingerprint\" },\n\"updates\": { \"url\": \"https://u.expo.dev/&lt;project-id&gt;\" }\n\n# Hotfix JS cho production, bắt đầu với 10% người dùng\neas update --channel production --message 'Fix report rounding' --rollout-percentage=10\neas update:edit       # tăng lên 50%, rồi 100%\neas update:rollback   # quay về update trước hoặc về bản nhúng trong build</pre>"},
  "w7k4": {c:"Đây là quy trình Apple và Google xét duyệt app trước khi phát hành: App Store Review kiểm tra theo App Review Guidelines (có người duyệt thủ công), Google Play review theo Developer Program Policies (phần lớn tự động), kèm các khai báo bắt buộc về quyền riêng tư và dữ liệu.", e:"<b>App Store</b>: upload qua Xcode, Transporter hoặc EAS Submit lên App Store Connect; TestFlight cho tester bên ngoài cũng phải qua một vòng review; điền metadata, ảnh chụp, nhãn quyền riêng tư, tài khoản demo; thời gian review thường trong khoảng một ngày. <b>Google Play</b>: tạo release trên một track (internal, closed, open, production), điền Data safety, khai báo quyền nhạy cảm, đạt mức target API level bắt buộc; tài khoản cá nhân mới phải chạy closed test với ít nhất 12 tester liên tục 14 ngày mới được lên production. Lý do bị reject hay gặp:<ul><li>Crash hoặc tính năng hỏng khi reviewer dùng, không đăng nhập được vì thiếu tài khoản demo (Guideline 2.1).</li><li>Chuỗi giải thích quyền mơ hồ, xin quyền không cần thiết.</li><li>Cho tạo tài khoản nhưng không cho xoá tài khoản ngay trong app (5.1.1).</li><li>Bán nội dung số mà không dùng In-App Purchase (3.1.1); metadata hoặc ảnh chụp không khớp app.</li><li>Có đăng nhập bên thứ ba nhưng thiếu một lựa chọn đăng nhập bảo vệ quyền riêng tư như Sign in with Apple (4.8).</li></ul> <b>Staged rollout</b>: Play cho chọn % và tạm dừng (halt); App Store có phased release 7 ngày cho bản cập nhật tự động, có thể pause.", x:"Bản đầu tiên của Expense Tracker bị Apple từ chối vì hai lý do: 5.1.1 (có đăng ký tài khoản nhưng không có chức năng xoá) và 2.1 (reviewer không đăng nhập được vì OTP gửi về số điện thoại). Cách xử lý: thêm mục “Xoá tài khoản” trong Settings gọi API xoá dữ liệu; tạo tài khoản demo không cần OTP và ghi vào App Review Information; trả lời trong Resolution Center mô tả thay đổi; nộp lại. Checklist trước mỗi lần nộp:<pre>[ ] Tài khoản demo và hướng dẫn trong App Review Information\n[ ] Chuỗi mô tả quyền cụ thể: 'Dùng camera để chụp hoá đơn'\n[ ] Có xoá tài khoản trong app (nếu cho tạo tài khoản)\n[ ] Privacy manifest, nhãn quyền riêng tư, Data safety khớp các SDK đang dùng\n[ ] Sign in with Apple (hoặc lựa chọn tương đương) nếu có login Google/Facebook\n[ ] Nội dung số trả phí dùng IAP, link thanh toán ngoài theo đúng quy định từng vùng\n[ ] Test bản release trên máy thật, mạng chậm, tài khoản chưa có dữ liệu</pre>"},
  "w7k5": {c:"System design mobile là dạng câu hỏi phỏng vấn về thiết kế kiến trúc tổng thể của một app hoặc một tính năng lớn: cách chia module, luồng dữ liệu từ API tới UI, lưu trữ, cache, đồng bộ offline, và các đánh đổi về hiệu năng, độ tin cậy, khả năng mở rộng cho team.", e:"<ul><li><b>Feature-based</b>: tổ chức theo tính năng (<code>features/transactions</code>, <code>features/budget</code>, <code>features/auth</code>), mỗi feature có <code>ui</code>, <code>hooks</code>, <code>api</code>, <code>model</code> riêng; phần dùng chung đặt ở <code>shared/</code> (design system, http client, utils); quy tắc import một chiều (feature không import phần nội bộ của feature khác) để nhiều người làm song song.</li><li><b>Phân lớp</b>: UI (screen, component) → state/hook (TanStack Query, store) → repository/service → data source (REST, DB local, secure store). UI không gọi <code>fetch</code> trực tiếp, nên đổi backend hay thêm cache chỉ đụng tới một lớp.</li><li><b>Cache</b>: memory (cache của Query), đĩa (persist query, MMKV, SQLite), ảnh (expo-image); có chính sách hết hạn, version cho schema, và xoá sạch khi logout.</li><li><b>Offline sync</b>: DB local là nguồn hiển thị; outbox lưu các thay đổi chờ gửi; có mạng thì đồng bộ (pull theo cursor <code>updatedAt</code>, push kèm idempotency key); xử lý xung đột (last-write-wins, theo version, hoặc hỏi người dùng); ID tạo ở client (UUID).</li></ul> Khi trả lời: làm rõ yêu cầu trước (người dùng, quy mô, mức độ offline), vẽ sơ đồ, nêu đánh đổi, và nhắc tới khả năng quan sát (log, crash, analytics) cùng bảo mật.", x:"Đề bài: “Thiết kế Expense Tracker dùng được offline và đồng bộ giữa nhiều thiết bị”. Khung trả lời trong 30 tới 40 phút:<pre>src/\n  features/transactions/{ui,hooks,api,repo,model}\n  features/budget/   features/auth/\n  shared/{design-system,http,db,sync,analytics}\n\nUI ── useTransactions() ── TxRepository ──┬─ SQLite (nguồn hiển thị)\n                                          └─ Outbox ── SyncEngine ── REST /sync\nSyncEngine: chạy khi online, khi app active, và mỗi 15 phút\n  push: gửi outbox theo thứ tự, header Idempotency-Key = id của thay đổi\n  pull: GET /sync?since=cursor → upsert vào local, lưu cursor mới\n  conflict: so version; xoá thắng sửa; còn lại last-write-wins theo giờ server</pre>"},
  "w7k6": {c:"STAR (Situation, Task, Action, Result) là khung kể chuyện cho câu hỏi hành vi: bối cảnh, nhiệm vụ của bạn, hành động cụ thể bạn đã làm, và kết quả đo được. Khung này dùng cho các câu như xử lý xung đột hay sự cố production.", e:"Nhà tuyển dụng dùng câu hỏi hành vi để đoán cách bạn sẽ làm việc sau này, nên câu trả lời phải là chuyện thật, cụ thể, và vai trò của “tôi” phải rõ ràng (không phải “team mình đã...”). Phân bổ: Situation và Task ngắn (khoảng 20%), Action chiếm phần lớn (lựa chọn, đánh đổi, vì sao), Result có số liệu và bài học. <b>Xung đột</b>: chọn chuyện bất đồng về kỹ thuật hoặc ưu tiên (với designer, backend, PM); cho thấy bạn lắng nghe, dùng dữ liệu, đề xuất phương án và chấp nhận thoả hiệp; tránh đổ lỗi hay kể kiểu “tôi đúng, họ sai”. <b>Sự cố production</b>: kể theo trình tự phát hiện → đánh giá ảnh hưởng → giảm thiệt hại (dừng rollout, kill switch) → tìm nguyên nhân → sửa → postmortem và phòng ngừa; cho thấy sự bình tĩnh và cách bạn giữ liên lạc với các bên. Chuẩn bị sẵn 5 tới 6 câu chuyện có thể xoay cho nhiều câu hỏi (thành tựu, thất bại, xung đột, mentor, deadline gấp, sự cố), tập nói thành tiếng khoảng 2 phút mỗi chuyện, bằng cả tiếng Việt và tiếng Anh nếu công ty cần.", x:"Câu hỏi: “Kể về một sự cố production bạn từng xử lý”. Câu trả lời mẫu theo STAR, khoảng 2 phút:<ul><li><b>S</b>: Sau bản 2.4, chỉ trong 2 giờ crash-free users giảm từ 99,6% xuống 97,9%, chủ yếu trên Android 13.</li><li><b>T</b>: Tôi là người on-call của team mobile, cần chặn ảnh hưởng và tìm nguyên nhân.</li><li><b>A</b>: Tôi dừng staged rollout ở 20% trên Play Console; đọc Sentry thấy crash ở màn quét hoá đơn do thư viện camera mới gọi một API chỉ có từ Android 14; tắt tính năng bằng Remote Config trong 15 phút; sửa bằng cách kiểm tra API level và thêm test trên emulator Android 13 vào CI; cập nhật tình hình trên kênh sự cố mỗi 30 phút.</li><li><b>R</b>: Crash-free trở lại 99,6% trong ngày, bản 2.4.1 rollout đủ sau 3 ngày; từ postmortem, team thêm quy định bắt buộc test theo ma trận API level cho mọi thư viện native mới.</li></ul> Phần bài học nên là một thay đổi về quy trình, không chỉ là “tôi cẩn thận hơn”."},
  "w7k7": {c:"Mock interview là buổi phỏng vấn thử, mô phỏng đúng các vòng thật (kỹ thuật, live coding, system design, hành vi) với một người đóng vai interviewer để luyện tập và nhận phản hồi; đi kèm là việc chỉnh CV và GitHub để thể hiện đúng năng lực cho vị trí Middle–Senior.", e:"<b>Mock interview</b>: làm ít nhất 2 buổi, mỗi buổi khoảng 60 phút theo cấu trúc thật (giới thiệu, kỹ thuật và live coding, system design hoặc hành vi, phần hỏi lại); nhờ bạn đi trước, mentor, hoặc dùng AI đóng vai interviewer; ghi âm hoặc quay lại để nghe cách mình diễn đạt; sau mỗi buổi ghi ba điểm cần sửa và luyện lại đúng chỗ đó. Chú ý nói ra suy nghĩ khi giải bài, hỏi lại yêu cầu, trả lời ngắn gọn có cấu trúc. <b>CV</b>: 1 tới 2 trang; mỗi dự án nêu vai trò, công nghệ (phiên bản RN, Expo hay bare, New Architecture, state management) và kết quả có số (giảm cold start 40%, crash-free 99,8%, 200 nghìn MAU); từ khoá khớp với JD; bỏ danh sách kỹ năng dài mà không chứng minh được. <b>GitHub</b>: ghim 2 tới 3 repo tốt nhất, README có ảnh hoặc video demo, cách chạy, sơ đồ kiến trúc, các quyết định kỹ thuật; có test, CI xanh, commit rõ ràng. Repo lab Expense Tracker của kế hoạch này là ứng viên tốt.", x:"Kịch bản mock buổi 1 (kỹ thuật) với một người bạn đóng vai interviewer, lấy câu hỏi từ mục Phỏng vấn của trang:<pre>00–05  Giới thiệu bản thân 90 giây (đã tập trước)\n05–20  JS/React: event loop, re-render, race condition trong useEffect\n20–40  Live coding: useDebouncedValue + màn tìm kiếm có huỷ request\n40–50  RN: FlatList 2.000 item bị giật, giải thích New Architecture\n50–55  Hỏi lại interviewer 2 câu\n55–60  Phản hồi: 3 điểm tốt, 3 điểm cần sửa</pre> Sau buổi, đối chiếu CV với câu trả lời: nếu CV ghi “tối ưu hiệu năng” mà không kể được số đo trước và sau, thì sửa CV hoặc chuẩn bị số liệu. Một dòng CV tốt: “Giảm cold start Android từ 4,2s xuống 2,1s bằng lazy load màn hình và trì hoãn SDK (RN 0.81, Hermes)”."},
  "w7k8": {c:"Staged rollout là phát hành bản mới dần dần cho một phần người dùng rồi tăng tỉ lệ khi các chỉ số ổn định; rollback là đưa người dùng về trạng thái an toàn khi bản mới có lỗi, với cách làm khác nhau giữa binary trên store và OTA update.", e:"<ul><li><b>Google Play</b>: chọn % người dùng nhận bản production (ví dụ 1% → 10% → 50% → 100%), có thể <b>halt</b> rollout. Người đã nhận bản mới không bị hạ cấp, nên “rollback” thực chất là phát hành bản sửa với <code>versionCode</code> cao hơn (có thể build lại từ code cũ).</li><li><b>App Store phased release</b>: áp dụng cho cập nhật tự động, kéo dài 7 ngày theo các mức 1%, 2%, 5%, 10%, 20%, 50%, 100%; có thể pause (tổng cộng tối đa 30 ngày); người dùng vẫn tự cập nhật thủ công được. Không rút lại được bản đã phát hành, chỉ có thể nộp bản mới và xin expedited review.</li><li><b>EAS Update</b>: phát update cho một % thiết bị (<code>--rollout-percentage</code>), chỉnh tỉ lệ bằng <code>eas update:edit</code>; rollback bằng <code>eas update:rollback</code> về update trước hoặc bản nhúng trong build, nhanh nhất trong ba cách.</li></ul> Theo dõi trước khi tăng %: crash-free users và sessions, tỉ lệ ANR, lỗi API, chỉ số nghiệp vụ (tỉ lệ thêm giao dịch thành công). Nên định nghĩa trước ngưỡng dừng (ví dụ crash-free dưới 99,5%) và kết hợp feature flag để tắt tính năng mà không cần phát hành.", x:"Kế hoạch phát hành 3.2.0 có tính năng đồng bộ mới, viết sẵn trước ngày release để không phải quyết định trong lúc vội:<pre>Ngày 0  Play 5% · App Store bật phased release · flag sync_v2 = 10% user\nNgày 1  crash-free ≥ 99,5%, ANR &lt; 0,3%, lỗi sync &lt; 1%  → Play 20%\nNgày 3  → Play 50%, flag sync_v2 = 50%\nNgày 5  → Play 100%, flag 100%\nDừng khi: crash-free &lt; 99,5% hoặc lỗi sync tăng gấp đôi\n  Play: Halt rollout · iOS: Pause phased release · flag sync_v2 = 0\n  Lỗi JS: eas update + rollout 10% (hoặc eas update:rollback nếu lỗi do OTA)\n  Lỗi native: build 3.2.1 (versionCode/CFBundleVersion mới), xin expedited review</pre>"},
  "w7k9": {c:"Portfolio của mobile developer là bằng chứng kiểm chứng được về sản phẩm bạn đã làm: link App Store hoặc Google Play của app đã phát hành, repo hoặc bản demo, kèm khả năng kể rõ vai trò của mình và kết quả đo được.", e:"Với vị trí Middle–Senior, nhà tuyển dụng muốn thấy bạn đã đưa app thật tới người dùng thật, không chỉ làm theo tutorial. Mỗi app trong portfolio nên có: link store (hoặc video nếu app nội bộ hay đã gỡ), một câu mô tả sản phẩm, quy mô (số người dùng, MAU, rating, số dev), vai trò cụ thể của bạn (lead mobile, viết module thanh toán, phụ trách release), công nghệ chính, và 2 tới 3 kết quả có số (giảm crash, tăng tốc startup, rút ngắn thời gian release). Phải tách rõ phần mình làm và phần team làm, vì interviewer sẽ hỏi sâu vào chi tiết kỹ thuật của chính phần đó. App công ty dưới NDA thì mô tả ở mức kiến trúc và những số liệu được phép công bố, không đưa code. Nếu chưa có app đã release, tự phát hành app lab Expense Tracker lên Google Play hoặc TestFlight là cách chứng minh bạn nắm toàn bộ quy trình signing, review, rollout. Chuẩn bị số liệu từ trước, đừng ước lượng tại chỗ.", x:"Viết lại mục portfolio từ kiểu liệt kê công nghệ sang kiểu có vai trò và số liệu:<pre>Trước:  App ví điện tử XPay – React Native, Redux, Firebase\n\nSau:    XPay (Android/iOS, 300k MAU, rating 4,6) · link App Store · link Google Play\n        Vai trò: 1 trong 4 mobile dev, phụ trách luồng nạp tiền và release.\n        - Chuyển 40 màn từ Redux viết tay sang TanStack Query, bỏ 6.000 dòng code.\n        - Giảm cold start Android từ 3,8s xuống 2,2s (lazy load, trì hoãn SDK, Hermes).\n        - Dựng pipeline EAS + GitHub Actions, thời gian release từ 2 ngày còn 2 giờ.\n        - Crash-free users từ 98,9% lên 99,7% nhờ Sentry và triage hằng tuần.</pre> Khi bị hỏi “cold start giảm bằng cách nào?”, phải kể được cách đo, công cụ đã dùng và từng thay đổi cụ thể."},
  "w7k10": {c:"Monorepo là cách đặt nhiều app và package (web, mobile, backend, thư viện dùng chung) trong cùng một repository; Nx và Turborepo là công cụ chạy build và test theo đồ thị phụ thuộc, có cache kết quả để chỉ chạy lại phần bị ảnh hưởng.", e:"Lợi ích chính với RN là chia sẻ code giữa web và mobile: <b>type</b> (model <code>Transaction</code>, DTO, schema zod), <b>API client</b> (hàm gọi REST/GraphQL, query key, hook TanStack Query), <b>logic thuần</b> (tính ngân sách, định dạng tiền, validate form), đôi khi cả design token. UI thường không chia sẻ trực tiếp (DOM khác View), trừ khi dùng React Native Web hoặc thư viện đa nền tảng. Workspace của package manager (npm, yarn, pnpm, bun) liên kết các package nội bộ; <b>Turborepo</b> nhẹ, cấu hình task trong <code>turbo.json</code>, có cache local và remote; <b>Nx</b> nhiều tính năng hơn (generator, lệnh <code>affected</code>, ràng buộc phụ thuộc giữa các module). Lưu ý riêng cho RN: Metro phải biết các thư mục workspace (Expo đã tự cấu hình monorepo trong <code>expo/metro-config</code> ở các SDK gần đây); toàn repo chỉ nên có một bản <code>react</code> và <code>react-native</code>, nếu không sẽ gặp lỗi “Invalid hook call” hoặc native module bị nhân đôi; package chung không được dùng API chỉ có trên web hay Node (<code>window</code>, <code>fs</code>). Trên CI, chỉ chạy phần bị đổi bằng <code>turbo run test --affected</code> hoặc <code>nx affected</code>.", x:"Web admin (Next.js) và app Expense Tracker cùng gọi API giao dịch, nhưng mỗi bên tự định nghĩa type; khi backend đổi field <code>amount</code> thành <code>amountMinor</code>, web đã sửa còn app thì crash. Chuyển sang monorepo để type và client dùng chung:<pre>apps/\n  mobile/   (Expo)    import { useTransactions } from '@expense/api'\n  web/      (Next.js)\npackages/\n  types/    Transaction, schema zod sinh từ OpenAPI\n  api/      http client, queryKeys, hook TanStack Query\n  core/     formatMoney, tính ngân sách (TS thuần, có unit test)\n\n// turbo.json\n{ \"tasks\": { \"build\": { \"dependsOn\": [\"^build\"], \"outputs\": [\"dist/**\"] },\n             \"test\": { \"dependsOn\": [\"^build\"] }, \"lint\": {} } }\n// CI: npx turbo run lint test --affected</pre>"},
  "w7k11": {c:"Live coding là vòng phỏng vấn viết code trực tiếp trong thời gian giới hạn khi interviewer quan sát; với RN thường là viết hàm JS/TS (debounce, retry, group by), một custom hook, hoặc một màn nhỏ có gọi API và hiển thị danh sách.", e:"Interviewer không chỉ đánh giá code có chạy đúng không mà còn cách bạn làm việc: hỏi lại yêu cầu và các trường hợp biên trước khi gõ, nói ra suy nghĩ, chia bước (cho bản đơn giản chạy được trước rồi mới cải tiến), đặt tên rõ ràng, xử lý trạng thái loading, error, empty, và tự kiểm tra bằng ví dụ. Luyện bằng cách bấm giờ như thật (30 tới 45 phút mỗi bài), tắt autocomplete AI nếu vòng thật không cho dùng, quay màn hình kèm giọng nói. Khi xem lại video, chấm theo các tiêu chí: mất bao lâu mới bắt đầu code, có hỏi lại yêu cầu không, có im lặng quá lâu không, có quên cleanup hay huỷ request không, cách đặt tên và chia cấu trúc, chỗ nào bị kẹt và vì sao. Mỗi bài ghi một dòng “lần sau làm khác” và làm lại bài kẹt nhất sau vài ngày. Chuẩn bị sẵn môi trường (Expo Snack, hoặc project trống có TypeScript và Jest) để không mất thời gian setup.", x:"Bài mẫu bấm giờ 30 phút: “Viết hook <code>useSearch(query)</code> gọi API tìm giao dịch, debounce 300 ms, huỷ request cũ, trả về <code>{ data, status }</code>”. Một bản đạt yêu cầu, với <code>type SearchState = { status: 'idle' | 'loading' | 'ok' | 'error'; data: Tx[] }</code>:<pre>function useSearch(query: string) {\n  const q = useDebouncedValue(query.trim(), 300);\n  const [state, setState] = useState&lt;SearchState&gt;({ status: 'idle', data: [] });\n  useEffect(() =&gt; {\n    if (!q) { setState({ status: 'idle', data: [] }); return; }\n    const ctrl = new AbortController();\n    setState(s =&gt; ({ ...s, status: 'loading' })); // giữ kết quả cũ trong lúc tải\n    fetch(`${API}/txs?q=${encodeURIComponent(q)}`, { signal: ctrl.signal })\n      .then(r =&gt; { if (!r.ok) throw new Error(String(r.status)); return r.json(); })\n      .then(data =&gt; setState({ status: 'ok', data }))\n      .catch(e =&gt; { if (e.name !== 'AbortError') setState(s =&gt; ({ ...s, status: 'error' })); });\n    return () =&gt; ctrl.abort();\n  }, [q]);\n  return state;\n}</pre> Khi tự review: đã nói lý do giữ <code>data</code> cũ lúc đang tải chưa, đã thử chuỗi rỗng, ký tự đặc biệt, gõ nhanh chưa, và có nhắc rằng ở production sẽ dùng TanStack Query không."}
};
